+  <script type="module">
+    const KEM_PUBLIC_KEY_ALGORITHMS = {
+      1184: 'ML-KEM-768',
+      1216: 'MLKEM768-X25519',
+      1568: 'ML-KEM-1024',
+    };
+
+    const IDB_NAME = 'daily-grind-crypto-store';
+    const IDB_STORE = 'kem-keys';
+
+    /**
+     * Converts a Uint8Array to Base64 using Uint8Array.prototype.toBase64 when available,
+     * with a standard btoa fallback.
+     * @param {Uint8Array} bytes
+     */
+    function bytesToBase64(bytes) {
+      const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
+      if (typeof view.toBase64 === 'function') {
+        return view.toBase64();
+      }
+      let binary = '';
+      for (let i = 0; i < view.byteLength; i++) {
+        binary += String.fromCharCode(view[i]);
+      }
+      return btoa(binary);
+    }
+
+    /**
+     * Checks whether the browser supports post-quantum KEM encapsulation + ChaCha20-Poly1305
+     * via the static SubtleCrypto.supports() method.
+     * @param {string} kemAlgorithm
+     */
+    export function supportsPostQuantumEnvelope(kemAlgorithm = 'MLKEM768-X25519') {
+      return (
+        typeof globalThis.SubtleCrypto?.supports === 'function' &&
+        SubtleCrypto.supports('encapsulateKey', kemAlgorithm, 'ChaCha20-Poly1305')
+      );
+    }
+
+    /**
+     * Opens IndexedDB to store non-extractable CryptoKeyPair objects across sessions
+     * via structured cloning without ever exporting private key bytes.
+     */
+    function openKeyDatabase() {
+      return new Promise((resolve, reject) => {
+        if (!('indexedDB' in globalThis)) {
+          resolve(null);
+          return;
+        }
+        const request = indexedDB.open(IDB_NAME, 1);
+        request.onupgradeneeded = () => {
+          const db = request.result;
+          if (!db.objectStoreNames.contains(IDB_STORE)) {
+            db.createObjectStore(IDB_STORE);
+          }
+        };
+        request.onsuccess = () => resolve(request.result);
+        request.onerror = () => resolve(null);
+      });
+    }
+
+    async function loadStoredKeyPair(storageKey) {
+      const db = await openKeyDatabase();
+      if (!db) return null;
+      return new Promise((resolve) => {
+        const tx = db.transaction(IDB_STORE, 'readonly');
+        const req = tx.objectStore(IDB_STORE).get(storageKey);
+        req.onsuccess = () => resolve(req.result || null);
+        req.onerror = () => resolve(null);
+      });
+    }
+
+    async function saveKeyPairToIndexedDB(storageKey, keyPair) {
+      const db = await openKeyDatabase();
+      if (!db) return;
+      return new Promise((resolve) => {
+        const tx = db.transaction(IDB_STORE, 'readwrite');
+        tx.objectStore(IDB_STORE).put(keyPair, storageKey);
+        tx.oncomplete = () => resolve();
+        tx.onerror = () => resolve();
+      });
+    }
+
+    /**
+     * Generates (or loads from IndexedDB) a recipient key pair using 'MLKEM768-X25519' (by default)
+     * or falls back to classical 'X25519' key agreement + 'HKDF' + 'AES-GCM'.
+     * @param {string} preferredKem
+     * @param {boolean} forceRotate
+     */
+    export async function generateRecipientKeys(
+      preferredKem = 'MLKEM768-X25519',
+      forceRotate = false,
+    ) {
+      const usePQ = supportsPostQuantumEnvelope(preferredKem);
+      const storageKey = usePQ ? `recipient-kem-key-${preferredKem}` : 'recipient-kem-key-X25519';
+
+      if (!forceRotate) {
+        const cachedKeyPair = await loadStoredKeyPair(storageKey);
+        if (cachedKeyPair?.publicKey && cachedKeyPair?.privateKey) {
