+  <link rel="stylesheet" href="/styles.css" blocking="render">
+
+  <!-- Preload critical hero background image so pixels are available before transition snapshot -->
+  <link
+    rel="preload"
+    as="image"
+    href="https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=1350&q=80"
+    fetchpriority="high"
+  >
+
+  <!-- Block rendering until above-the-fold hero and Seasonal Favorites sections are parsed (without waiting on footer) -->
+  <link rel="expect" href="#hero" blocking="render">
+  <link rel="expect" href="#seasonal-favorites" blocking="render">
+
+  <!-- Initial theme and layout setup scripts marked with blocking="render" -->
+  <script type="module" blocking="render" src="/theme-layout.js"></script>
+  <script type="module" blocking="render">
+    document.documentElement.dataset.theme =
+      localStorage.getItem('theme') || 'light';
+    document.documentElement.dataset.layout =
+      localStorage.getItem('layout') || 'grid';
+  </script>
+
+  <style blocking="render">
+    @view-transition {
+      navigation: auto;
+    }
+
+    @media (prefers-reduced-motion: reduce) {
+      @view-transition {
+        navigation: none;
+      }
+    }
+  </style>
+</head>
+
+<body>
+
+  <nav id="site-nav">
+    <div class="logo"><a href="/">THE DAILY GRIND</a></div>
+    <ul>
+      <li><a href="/menu" aria-current="page">Menu</a></li>
+      <li><a href="/locations">Locations</a></li>
+      <li><a href="/rewards">Rewards</a></li>
+      <li><a href="/account">My Account</a></li>
+      <li><a href="/logout" class="logout-link">Logout</a></li>
+    </ul>
+  </nav>
+
+  <header id="hero" class="hero">
+    <h1>Our Artisanal Menu</h1>
+    <p>Handcrafted espresso, small-batch cold brews, and seasonal specialties.</p>
+    <a href="/order-online" class="btn">Order Online</a>
+  </header>
+
+  <main id="main-content" class="container">
+    <section id="seasonal-favorites">
+      <h2 style="text-align: center;">Seasonal Favorites</h2>
+      <div class="grid">
+        <div class="card" style="view-transition-name: card-maple-latte;">
+          <h3>Maple Oat Latte</h3>
+          <p>Creamy oat milk with a hint of Vermont maple syrup. $5.75</p>
+          <a href="/menu/seasonal" class="btn">View Details</a>
+        </div>
+        <div class="card" style="view-transition-name: card-dark-espresso;">
+          <h3>Dark Roast Espresso</h3>
+          <p>Bold, smokey, and perfect for a morning boost. $3.50</p>
+          <a href="/menu/espresso" class="btn">View Details</a>
+        </div>
+        <div class="card" style="view-transition-name: card-cold-brew;">
+          <h3>Cold Brew</h3>
+          <p>Steeped for 18 hours for maximum smoothness. $4.75</p>
+          <a href="/menu/cold-brew" class="btn">View Details</a>
+        </div>
+      </div>
+    </section>
+
+    <section id="bakery-pairings" style="margin-top: 40px;">
+      <h2 style="text-align: center;">Fresh Bakery Pairings</h2>
+      <div class="grid">
+        <div class="card">
+          <h3>Cardamom Morning Bun</h3>
+          <p>Flaky laminated pastry tossed in freshly ground cardamom sugar. $4.25</p>
+        </div>
+        <div class="card">
+          <h3>Almond Croissant</h3>
+          <p>Twice-baked butter croissant filled with toasted almond frangipane. $4.75</p>
+        </div>
+        <div class="card">
+          <h3>Rosemary Sea Salt Focaccia</h3>
+          <p>Warm house-baked focaccia brushed with extra-virgin olive oil. $5.00</p>
+        </div>
+      </div>
+    </section>
+  </main>
+
+  <footer>
+    <div class="footer-links">
+      <a href="/about">Our Story</a> |
+      <a href="/careers">Join the Team</a> |
+      <a href="/contact">Contact Us</a> |
+      <a href="/privacy-policy">Privacy</a>
+    </div>
+    <p>&copy; 2026 The Daily Grind Coffee Co. All rights reserved.</p>
+  </footer>
+
+</body>
+
+</html>
