+// smallpt, a Path Tracer by Kevin Beason, 2008
+// Make : g++ -O3 -fopenmp smallpt.cpp -o smallpt
+//        Remove "-fopenmp" for g++ version < 4.2
+// Usage: time ./smallpt 5000 && xv image.ppm
+// Extended with WebAssembly exports for interactive browser rendering & randomized sphere colors.
+
+#include <math.h>   // smallpt, a Path Tracer by Kevin Beason, 2008
+#include <stdlib.h> // Make : g++ -O3 -fopenmp smallpt.cpp -o smallpt
+#include <stdio.h>  //        Remove "-fopenmp" for g++ version < 4.2
+#include <stdint.h>
+
+#ifdef __EMSCRIPTEN__
+#include <emscripten/emscripten.h>
+#define EXPORT EMSCRIPTEN_KEEPALIVE
+#else
+#define EXPORT
+#endif
+
+struct Vec {        // Usage: time ./smallpt 5000 && xv image.ppm
+  double x, y, z;                  // position, also color (r,g,b)
+  Vec(double x_=0, double y_=0, double z_=0){ x=x_; y=y_; z=z_; }
+  Vec operator+(const Vec &b) const { return Vec(x+b.x,y+b.y,z+b.z); }
+  Vec operator-(const Vec &b) const { return Vec(x-b.x,y-b.y,z-b.z); }
+  Vec operator*(double b) const { return Vec(x*b,y*b,z*b); }
+  Vec mult(const Vec &b) const { return Vec(x*b.x,y*b.y,z*b.z); }
+  Vec& norm(){ return *this = *this * (1/sqrt(x*x+y*y+z*z)); }
+  double dot(const Vec &b) const { return x*b.x+y*b.y+z*b.z; } // cross:
+  Vec operator%(Vec&b){return Vec(y*b.z-z*b.y,z*b.x-x*b.z,x*b.y-y*b.x);}
+};
+struct Ray { Vec o, d; Ray(Vec o_, Vec d_) : o(o_), d(d_) {} };
+enum Refl_t { DIFF, SPEC, REFR };  // material types, used in radiance()
+struct Sphere {
+  double rad;       // radius
+  Vec p, e, c;      // position, emission, color
+  Refl_t refl;      // reflection type (DIFFuse, SPECular, REFRactive)
+  Sphere(double rad_, Vec p_, Vec e_, Vec c_, Refl_t refl_):
+    rad(rad_), p(p_), e(e_), c(c_), refl(refl_) {}
+  double intersect(const Ray &r) const { // returns distance, 0 if nohit
+    Vec op = p-r.o; // Solve t^2*d.d + 2*t*(o-p).d + (o-p).(o-p)-R^2 = 0
+    double t, eps=1e-4, b=op.dot(r.d), det=b*b-op.dot(op)+rad*rad;
+    if (det<0) return 0; else det=sqrt(det);
+    return (t=b-det)>eps ? t : ((t=b+det)>eps ? t : 0);
+  }
+};
+Sphere spheres[] = {//Scene: radius, position, emission, color, material
+  Sphere(1e5, Vec( 1e5+1,40.8,81.6), Vec(),Vec(.75,.25,.25),DIFF),//Left
+  Sphere(1e5, Vec(-1e5+99,40.8,81.6),Vec(),Vec(.25,.25,.75),DIFF),//Rght
+  Sphere(1e5, Vec(50,40.8, 1e5),     Vec(),Vec(.75,.75,.75),DIFF),//Back
+  Sphere(1e5, Vec(50,40.8,-1e5+170), Vec(),Vec(),           DIFF),//Frnt
+  Sphere(1e5, Vec(50, 1e5, 81.6),    Vec(),Vec(.75,.75,.75),DIFF),//Botm
+  Sphere(1e5, Vec(50,-1e5+81.6,81.6),Vec(),Vec(.75,.75,.75),DIFF),//Top
+  Sphere(16.5,Vec(27,16.5,47),       Vec(),Vec(1,1,1)*.999, SPEC),//Mirr
+  Sphere(16.5,Vec(73,16.5,78),       Vec(),Vec(1,1,1)*.999, REFR),//Glas
+  Sphere(600, Vec(50,681.6-.27,81.6),Vec(12,12,12),  Vec(), DIFF) //Lite
+};
+inline double clamp(double x){ return x<0 ? 0 : x>1 ? 1 : x; }
+inline int toInt(double x){ return int(pow(clamp(x),1/2.2)*255+.5); }
+inline bool intersect(const Ray &r, double &t, int &id){
+  double n=sizeof(spheres)/sizeof(Sphere), d, inf=t=1e20;
+  for(int i=int(n);i--;) if((d=spheres[i].intersect(r))&&d<t){t=d;id=i;}
+  return t<inf;
+}
+Vec radiance(const Ray &r, int depth, unsigned short *Xi){
+  double t;                               // distance to intersection
+  int id=0;                               // id of intersected object
+  if (!intersect(r, t, id)) return Vec(); // if miss, return black
+  const Sphere &obj = spheres[id];        // the hit object
+  Vec x=r.o+r.d*t, n=(x-obj.p).norm(), nl=n.dot(r.d)<0?n:n*-1, f=obj.c;
+  double p = f.x>f.y && f.x>f.z ? f.x : f.y>f.z ? f.y : f.z; // max refl
+  if (++depth>5) { if (erand48(Xi)<p) f=f*(1/p); else return obj.e; } //R.R.
+  if (depth>100) return obj.e; // prevent stack overflow on high albedo
+  if (obj.refl == DIFF){                  // Ideal DIFFUSE reflection
+    double r1=2*M_PI*erand48(Xi), r2=erand48(Xi), r2s=sqrt(r2);
+    Vec w=nl, u=((fabs(w.x)>.1?Vec(0,1):Vec(1))%w).norm(), v=w%u;
+    Vec d = (u*cos(r1)*r2s + v*sin(r1)*r2s + w*sqrt(1-r2)).norm();
+    return obj.e + f.mult(radiance(Ray(x,d),depth,Xi));
+  } else if (obj.refl == SPEC)            // Ideal SPECULAR reflection
+    return obj.e + f.mult(radiance(Ray(x,r.d-n*2*n.dot(r.d)),depth,Xi));
+  Ray reflRay(x, r.d-n*2*n.dot(r.d));     // Ideal dielectric REFRACTION
+  bool into = n.dot(nl)>0;                // Ray from outside going in?
+  double nc=1, nt=1.5, nnt=into?nc/nt:nt/nc, ddn=r.d.dot(nl), cos2t;
+  if ((cos2t=1-nnt*nnt*(1-ddn*ddn))<0)    // Total internal reflection
+    return obj.e + f.mult(radiance(reflRay,depth,Xi));
+  Vec tdir = (r.d*nnt - n*((into?1:-1)*(ddn*nnt+sqrt(cos2t)))).norm();
+  double a=nt-nc, b=nt+nc, R0=a*a/(b*b), c = 1-(into?-ddn:tdir.dot(n));
+  double Re=R0+(1-R0)*c*c*c*c*c,Tr=1-Re,P=.25+.5*Re,RP=Re/P,TP=Tr/(1-P);
+  return obj.e + f.mult(depth>2 ? (erand48(Xi)<P ?   // Russian roulette
+    radiance(reflRay,depth,Xi)*RP:radiance(Ray(x,tdir),depth,Xi)*TP) :
+    radiance(reflRay,depth,Xi)*Re+radiance(Ray(x,tdir),depth,Xi)*Tr);
+}
+
+// Persistent buffers for progressive/interactive WebAssembly rendering
+static int g_w = 0;
+static int g_h = 0;
+static int g_total_samples = 0;
+static Vec *g_accum = NULL;
+static uint8_t *g_rgba = NULL;
+static unsigned int g_rng_seed = 1337;
+
+static double rand_unit() {
+  g_rng_seed = g_rng_seed * 1664525u + 1013904223u;
+  return (g_rng_seed & 0xFFFFFF) / double(0x1000000);
+}
+
+static Vec hsv_to_rgb(double h, double s, double v) {
+  double c = v * s;
+  double x = c * (1.0 - fabs(fmod(h * 6.0, 2.0) - 1.0));
+  double m = v - c;
+  double r = 0, g = 0, b = 0;
+  int i = int(h * 6.0);
+  switch (i % 6) {
+    case 0: r = c; g = x; b = 0; break;
+    case 1: r = x; g = c; b = 0; break;
+    case 2: r = 0; g = c; b = x; break;
+    case 3: r = 0; g = x; b = c; break;
+    case 4: r = x; g = 0; b = c; break;
+    case 5: r = c; g = 0; b = x; break;
+  }
+  return Vec(r + m, g + m, b + m);
+}
+
+extern "C" {
+
+EXPORT void reset_default_colors() {
+  spheres[0].c = Vec(.75, .25, .25); // Left
+  spheres[1].c = Vec(.25, .25, .75); // Right
+  spheres[2].c = Vec(.75, .75, .75); // Back
+  spheres[3].c = Vec(0, 0, 0);       // Front
+  spheres[4].c = Vec(.75, .75, .75); // Bottom
+  spheres[5].c = Vec(.75, .75, .75); // Top
+  spheres[6].c = Vec(1, 1, 1) * .999; // Mirror
+  spheres[7].c = Vec(1, 1, 1) * .999; // Glass
+}
+
+EXPORT void set_sphere_color(int index, double r, double g, double b) {
+  if (index >= 0 && index < 9) {
+    spheres[index].c = Vec(clamp(r), clamp(g), clamp(b));
+  }
+}
+
+EXPORT double get_sphere_color_r(int index) {
+  return (index >= 0 && index < 9) ? spheres[index].c.x : 0.0;
+}
+
+EXPORT double get_sphere_color_g(int index) {
+  return (index >= 0 && index < 9) ? spheres[index].c.y : 0.0;
+}
+
+EXPORT double get_sphere_color_b(int index) {
+  return (index >= 0 && index < 9) ? spheres[index].c.z : 0.0;
+}
+
+EXPORT void randomize_sphere_colors(unsigned int seed) {
+  if (seed != 0) g_rng_seed = seed;
+  // Left wall: vibrant random hue
+  double h1 = rand_unit();
+  spheres[0].c = hsv_to_rgb(h1, 0.65 + 0.25 * rand_unit(), 0.70 + 0.20 * rand_unit());
+  // Right wall: complementary/contrasting hue
+  double h2 = fmod(h1 + 0.35 + 0.30 * rand_unit(), 1.0);
+  spheres[1].c = hsv_to_rgb(h2, 0.65 + 0.25 * rand_unit(), 0.70 + 0.20 * rand_unit());
+  // Back wall: soft tinted hue
+  double h3 = rand_unit();
+  spheres[2].c = hsv_to_rgb(h3, 0.25 + 0.35 * rand_unit(), 0.75 + 0.15 * rand_unit());
+  // Bottom floor: subtle warm/cool tint
+  spheres[4].c = hsv_to_rgb(rand_unit(), 0.20 + 0.30 * rand_unit(), 0.75 + 0.15 * rand_unit());
+  // Top ceiling: light neutral/pastel
+  spheres[5].c = hsv_to_rgb(rand_unit(), 0.10 + 0.20 * rand_unit(), 0.80 + 0.15 * rand_unit());
+  // Mirror sphere: metallic tint (gold, copper, rose, cyan, or silver)
+  spheres[6].c = hsv_to_rgb(rand_unit(), 0.35 + 0.50 * rand_unit(), 0.90 + 0.099 * rand_unit());
+  // Glass sphere: colored crystal tint
+  spheres[7].c = hsv_to_rgb(rand_unit(), 0.30 + 0.50 * rand_unit(), 0.92 + 0.079 * rand_unit());
+}
+
+EXPORT void init_scene(int w, int h) {
+  if (w != g_w || h != g_h || !g_accum || !g_rgba) {
+    delete[] g_accum;
+    delete[] g_rgba;
+    g_w = w;
+    g_h = h;
+    g_accum = new Vec[w * h];
+    g_rgba = new uint8_t[w * h * 4];
+  }
+  for (int i = 0; i < w * h; i++) {
+    g_accum[i] = Vec(0, 0, 0);
+  }
+  for (int i = 0; i < w * h * 4; i += 4) {
+    g_rgba[i] = 0;
+    g_rgba[i + 1] = 0;
+    g_rgba[i + 2] = 0;
+    g_rgba[i + 3] = 255;
+  }
+  g_total_samples = 0;
+}
+
+// Scanline progressive render: renders [y_start, y_end) for the current pass
+EXPORT int render_scanlines(int y_start, int y_end, int samps) {
+  if (!g_accum || !g_rgba || g_w <= 0 || g_h <= 0) return 0;
+  if (samps < 1) samps = 1;
+  int w = g_w;
+  int h = g_h;
+  if (y_start < 0) y_start = 0;
+  if (y_end > h) y_end = h;
+  int pass_offset = g_total_samples;
+
+  Ray cam(Vec(50, 52, 295.6), Vec(0, -0.042612, -1).norm());
+  Vec cx = Vec(w * .5135 / h);
+  Vec cy = (cx % cam.d).norm() * .5135;
+
+  double inv_passes = 4.0 / double(g_total_samples + samps * 4);
+
+  for (int y = y_start; y < y_end; y++) {
+    unsigned short Xi[3] = {
+      (unsigned short)(y + pass_offset * 17),
+      (unsigned short)(y * y + pass_offset * 31 + (g_rng_seed & 0xFFFF)),
+      (unsigned short)(y * y * y + pass_offset * 97 + ((g_rng_seed >> 16) & 0xFFFF))
+    };
+    for (unsigned short x = 0; x < w; x++) {
+      Vec pixel_pass(0, 0, 0);
+      for (int sy = 0; sy < 2; sy++) {
+        for (int sx = 0; sx < 2; sx++) {
+          Vec r(0, 0, 0);
+          for (int s = 0; s < samps; s++) {
+            double r1 = 2 * erand48(Xi), dx = r1 < 1 ? sqrt(r1) - 1 : 1 - sqrt(2 - r1);
+            double r2 = 2 * erand48(Xi), dy = r2 < 1 ? sqrt(r2) - 1 : 1 - sqrt(2 - r2);
+            Vec d = cx * (((sx + .5 + dx) / 2 + x) / w - .5) +
+                    cy * (((sy + .5 + dy) / 2 + y) / h - .5) + cam.d;
