+      }
+
+      updateSwatches();
+
+      // Run initial passes synchronously so the canvas updates immediately
+      const passes = wasmMod._render_pass(PASSES_PER_STEP);
+      renderCount += 1;
+
+      const canvas = document.getElementById("smallpt-canvas");
+      if (canvas) {
+        canvas.setAttribute("data-render-count", String(renderCount));
+        canvas.setAttribute("data-seed", String(currentSeed));
+      }
+
+      blitToCanvas(passes);
+      if (passes < TARGET_PASSES) {
+        scheduleNextPass();
+      }
+    }
+
+    async function initSmallpt() {
+      const canvas = document.getElementById("smallpt-canvas");
+      if (!canvas) return;
+
+      if (!wasmMod && typeof window.createSmallptModule === "function") {
+        wasmMod = await window.createSmallptModule({
+          locateFile: function (file) {
+            return baseUrl + file;
+          },
+        });
+        wasmMod._init_renderer(WIDTH, HEIGHT);
+      }
+
+      if (!wasmMod) return;
+
+      const randomizeBtn = document.getElementById("randomize-colors-btn");
+      if (randomizeBtn && !randomizeBtn.dataset.bound) {
+        randomizeBtn.dataset.bound = "true";
+        randomizeBtn.addEventListener("click", function () {
+          startRender(true);
+        });
+      }
+
+      const resetBtn = document.getElementById("reset-colors-btn");
+      if (resetBtn && !resetBtn.dataset.bound) {
+        resetBtn.dataset.bound = "true";
+        resetBtn.addEventListener("click", function () {
+          currentSeed = 0;
+          wasmMod._reset_sphere_colors();
+          startRender(false);
+        });
+      }
+
+      startRender(false);
+    }
+
+    if (document.readyState === "loading") {
+      document.addEventListener("DOMContentLoaded", initSmallpt);
+    } else {
+      initSmallpt();
+    }
+    document.addEventListener("astro:page-load", initSmallpt);
+  })();
+</script>
