+        if (routeTrigger.getAttribute('data-action') === 'logout' || routeTrigger.getAttribute('href') === '/logout') {
+          event.preventDefault();
+          activateView('account', { pushState: true });
+          var statusEl = document.getElementById('account-save-status');
+          if (statusEl) {
+            statusEl.textContent = 'Session active (Demo Mode). Manage your account preferences below.';
+          }
