+          return;
+        }
+
+        var href = routeTrigger.getAttribute('data-route') || routeTrigger.getAttribute('href') || '/';
+        var targetView = 'home';
+        if (href.indexOf('/menu') === 0) targetView = 'menu';
+        else if (href.indexOf('/locations') === 0) targetView = 'locations';
+        else if (href.indexOf('/rewards') === 0) targetView = 'rewards';
+        else if (href.indexOf('/account') === 0) targetView = 'account';
+        else if (href === '/') targetView = 'home';
+        else return;
+
+        event.preventDefault();
+
+        var preselectCategory = routeTrigger.getAttribute('data-category-select');
+        activateView(targetView, { pushState: true });
