+
+      // Support keyboard navigation on the logo
+      var logoEl = document.querySelector('.logo[data-route]');
+      if (logoEl) {
+        logoEl.addEventListener('keydown', function (event) {
+          if (event.key === 'Enter' || event.key === ' ') {
+            event.preventDefault();
+            activateView('home', { pushState: true });
+          }
+        });
+      }
+
+      // Handle browser back/forward navigation
+      window.addEventListener('popstate', function (event) {
+        var stateView = event.state && event.state.view ? event.state.view : resolveViewFromLocation();
