+      });
+
+      window.addEventListener('hashchange', function () {
+        var viewFromHash = resolveViewFromLocation();
+        activateView(viewFromHash, { pushState: false });
+      });
+
+      // --- Interactive View Logic (preserved in DOM across view switches) ---
+
+      // 1. Menu filtering, search, and order bag
+      var menuSearchInput = document.getElementById('menu-search');
+      var menuFilterBtns = Array.prototype.slice.call(document.querySelectorAll('#view-menu .filter-btn'));
+      var menuItems = Array.prototype.slice.call(document.querySelectorAll('#view-menu .menu-item'));
+      var activeMenuCategory = 'all';
+      var orderCount = 0;
+      var orderTotal = 0;
+
+      function filterMenuItems() {
+        var query = (menuSearchInput ? menuSearchInput.value : '').trim().toLowerCase();
+        menuItems.forEach(function (item) {
+          var itemCat = item.getAttribute('data-category');
+          var itemText = item.textContent.toLowerCase();
+          var matchesCategory = activeMenuCategory === 'all' || itemCat === activeMenuCategory;
+          var matchesQuery = !query || itemText.indexOf(query) !== -1;
+          item.style.display = matchesCategory && matchesQuery ? '' : 'none';
+        });
+      }
+
+      function setMenuCategory(category) {
+        activeMenuCategory = category || 'all';
+        menuFilterBtns.forEach(function (btn) {
+          btn.classList.toggle('active', btn.getAttribute('data-category') === activeMenuCategory);
+        });
+        filterMenuItems();
+      }
+
+      menuFilterBtns.forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          setMenuCategory(btn.getAttribute('data-category'));
+        });
+      });
+
+      if (menuSearchInput) {
+        menuSearchInput.addEventListener('input', filterMenuItems);
+      }
+
+      function updateOrderDisplay() {
+        var countEl = document.getElementById('order-count');
+        var totalEl = document.getElementById('order-total');
+        if (countEl) countEl.textContent = orderCount + (orderCount === 1 ? ' item' : ' items');
+        if (totalEl) totalEl.textContent = '$' + orderTotal.toFixed(2);
+      }
+
+      document.querySelectorAll('.add-to-order-btn').forEach(function (btn) {
+        var addedCount = 0;
+        var baseLabel = btn.textContent;
+        btn.addEventListener('click', function () {
+          var price = parseFloat(btn.getAttribute('data-price') || '0');
+          orderCount += 1;
+          addedCount += 1;
+          orderTotal += price;
+          btn.textContent = baseLabel + ' (' + addedCount + ')';
+          updateOrderDisplay();
+        });
+      });
+
+      var clearOrderBtn = document.getElementById('clear-order-btn');
+      if (clearOrderBtn) {
+        clearOrderBtn.addEventListener('click', function () {
+          orderCount = 0;
+          orderTotal = 0;
+          document.querySelectorAll('.add-to-order-btn').forEach(function (btn) {
+            btn.textContent = 'Add to Order';
+          });
+          updateOrderDisplay();
+        });
+      }
+
+      // 2. Locations search and preferred cafe selection
+      var locationSearchInput = document.getElementById('location-search');
+      var locationCards = Array.prototype.slice.call(document.querySelectorAll('#view-locations .location-card'));
+      var locationSelectBtns = Array.prototype.slice.call(document.querySelectorAll('.select-location-btn'));
+
+      if (locationSearchInput) {
+        locationSearchInput.addEventListener('input', function () {
+          var query = locationSearchInput.value.trim().toLowerCase();
+          locationCards.forEach(function (card) {
+            var text = (card.textContent + ' ' + (card.getAttribute('data-keywords') || '')).toLowerCase();
+            card.style.display = !query || text.indexOf(query) !== -1 ? '' : 'none';
+          });
+        });
+      }
+
+      locationSelectBtns.forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          var chosen = btn.getAttribute('data-location-title');
+          var preferredLabel = document.getElementById('preferred-location-name');
+          var accountCafeLabel = document.getElementById('account-preferred-cafe');
+          if (preferredLabel) preferredLabel.textContent = chosen;
+          if (accountCafeLabel) accountCafeLabel.textContent = chosen;
+
+          locationSelectBtns.forEach(function (otherBtn) {
+            var isSelected = otherBtn === btn;
+            otherBtn.classList.toggle('btn-secondary', !isSelected);
+            otherBtn.textContent = isSelected ? 'Preferred Cafe ✓' : 'Set as Preferred';
+          });
+        });
+      });
+
+      // 3. Rewards redemption and promo code
+      var pointsBalance = 340;
+      var pointsEl = document.getElementById('rewards-points');
+      var feedbackEl = document.getElementById('rewards-feedback');
+      var promoInput = document.getElementById('rewards-promo');
+      var applyPromoBtn = document.getElementById('apply-promo-btn');
+
+      function updatePointsUI() {
+        if (pointsEl) pointsEl.textContent = String(pointsBalance);
+        var fill = document.getElementById('rewards-progress-fill');
+        if (fill) {
+          var pct = Math.min(100, Math.round((pointsBalance / 400) * 100));
+          fill.style.width = pct + '%';
+        }
+      }
+
+      if (applyPromoBtn && promoInput) {
+        applyPromoBtn.addEventListener('click', function () {
+          var code = promoInput.value.trim().toUpperCase();
+          if (!code) return;
+          pointsBalance += 50;
+          updatePointsUI();
+          if (feedbackEl) {
+            feedbackEl.textContent = 'Applied code "' + code + '" (+50 Beans)!';
+          }
+        });
+      }
+
+      document.querySelectorAll('.redeem-btn').forEach(function (btn) {
+        btn.addEventListener('click', function () {
+          var cost = parseInt(btn.getAttribute('data-cost') || '0', 10);
+          var rewardName = btn.getAttribute('data-reward');
+          if (pointsBalance >= cost) {
+            pointsBalance -= cost;
+            updatePointsUI();
+            btn.textContent = 'Redeemed ✓';
+            btn.dataset.redeemed = 'true';
+            if (feedbackEl) {
+              feedbackEl.textContent = 'Redeemed: ' + rewardName + '!';
+            }
+          } else if (feedbackEl) {
+            feedbackEl.textContent = 'Need ' + (cost - pointsBalance) + ' more Beans to redeem ' + rewardName + '.';
+          }
+        });
+      });
+
+      // 4. My Account preferences form & quick reorder
+      var accountForm = document.getElementById('account-preferences-form');
+      var accountStatus = document.getElementById('account-save-status');
+      if (accountForm) {
+        accountForm.addEventListener('submit', function (event) {
+          event.preventDefault();
+          var nameInput = document.getElementById('account-name');
+          var userName = nameInput ? nameInput.value.trim() : 'Member';
+          if (accountStatus) {
+            accountStatus.textContent = 'Preferences saved for ' + userName + '!';
+          }
+        });
+      }
+
+      var quickReorderBtn = document.getElementById('quick-reorder-btn');
+      if (quickReorderBtn) {
+        quickReorderBtn.addEventListener('click', function () {
+          orderCount += 2;
+          orderTotal += 10.0;
+          updateOrderDisplay();
+          quickReorderBtn.textContent = 'Added Usual Order to Bag ✓';
+        });
+      }
+
+      // Initialize view based on initial URL
+      var initialView = resolveViewFromLocation();
+      activateView(initialView, { replaceState: true, resetScroll: true });
+    })();
+  </script>
 </body>

 </html>

