+type LnaPermissionName = 'local-network' | 'loopback-network';
+type PermissionStateValue = PermissionState | 'unsupported';
+type ConnectionStatus = 'idle' | 'connecting' | 'connected' | 'error';
+
+/**
+ * Cross-browser permission check for the granular LNA permissions.
+ * Never falls back to querying 'local-network-access', which crashes older Chrome versions.
+ */
+export async function queryLnaPermissionSafe(
+  permissionName: LnaPermissionName,
+  onChange?: (state: PermissionState) => void
+): Promise<{ state: PermissionState; cleanup?: () => void }> {
+  if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
+    return { state: 'prompt' };
+  }
+  try {
+    const status = await navigator.permissions.query({
+      name: permissionName as PermissionName,
+    });
+    const handleChange = () => {
+      onChange?.(status.state);
+    };
+    status.addEventListener('change', handleChange);
+    return {
+      state: status.state,
+      cleanup: () => status.removeEventListener('change', handleChange),
+    };
+  } catch {
+    // Unrecognized permission name in browsers without LNA support; proceed on user gesture
+    return { state: 'prompt' };
+  }
+}
+
+/**
+ * Connects to a local network device (e.g., hardware test device on 192.168.1.x or .local) over HTTP.
+ */
+export async function fetchLocalDeviceStatus(
+  deviceUrl = 'http://192.168.1.100:8080/api/diagnostics'
+) {
+  const request = new Request(deviceUrl, {
+    method: 'GET',
+    mode: 'cors',
+    // MANDATORY: Declare 'local' when targeting RFC 1918 / .local LAN addresses
+    targetAddressSpace: 'local',
+  } as RequestInit);
+
+  const response = await fetch(request);
+  if (!response.ok) {
+    throw new Error(`Hardware device responded with HTTP ${response.status}`);
+  }
+  return response.json();
+}
