+        const playStateValue = isBannerPaused ? 'paused' : 'running';
+
+        roastBanner.classList.toggle('is-paused', isBannerPaused);
+        roastBanner.classList.toggle('paused', isBannerPaused);
+        roastBanner.setAttribute('data-paused', String(isBannerPaused));
+        roastBanner.style.animationPlayState = playStateValue;
+
+        roastTrack.classList.toggle('is-paused', isBannerPaused);
+        roastTrack.classList.toggle('paused', isBannerPaused);
