+            </button>
+          </form>
+        </div>
+
+        {/* Browser Authenticator Synchronization Activity Log */}
+        <div className="border-t border-gray-200 pt-6">
+          <div className="flex items-center justify-between mb-2">
+            <h3 className="text-xs font-bold uppercase tracking-wider text-gray-500">
+              Browser Authenticator Sync Log (WebAuthn Signal API)
+            </h3>
+            <span className="text-xs text-gray-500">
+              RP ID: <code className="font-mono">{getRpId()}</code>
+            </span>
+          </div>
+          {syncEvents.length === 0 ? (
+            <p className="text-xs text-gray-500">
+              No authenticator sync signals emitted yet.
+            </p>
+          ) : (
+            <div
+              data-testid="authenticator-sync-log"
+              className="bg-gray-900 text-gray-100 rounded-md p-3.5 text-xs font-mono space-y-2 max-h-48 overflow-y-auto"
+            >
+              {syncEvents.map((ev) => (
+                <div
+                  key={ev.id}
+                  className="border-b border-gray-800 pb-2 last:border-b-0 last:pb-0"
+                >
+                  <div className="flex items-center justify-between text-amber-400">
+                    <span>PublicKeyCredential.{ev.method}()</span>
+                    <span className="text-gray-400 text-[11px]">
+                      {ev.status === 'synced' ? 'SYNCED' : 'SIGNAL READY'}
+                    </span>
+                  </div>
+                  <p className="text-gray-300 mt-0.5 font-sans">{ev.summary}</p>
+                  <pre className="text-[11px] text-gray-400 overflow-x-auto mt-1">
+                    {JSON.stringify(ev.payload)}
+                  </pre>
+                </div>
+              ))}
+            </div>
+          )}
+        </div>
+      </div>
+    </section>
+  );
+}
