+            // If user canceled or environment lacks physical authenticator, fall back cleanly if virtual toggle is on or auto-fallback
+            console.warn('Native WebAuthn create fell back to Virtual Passkey Authenticator:', nativeErr);
+          }
+        }
+
+        // Virtual WebAuthn Passkey Authenticator Creation
+        const simulatedRawId = generateRandomBytes(24);
+        const credId = bufferToBase64Url(simulatedRawId);
+        return {
+          id: credId,
+          nickname: nickname || 'Device Passkey',
+          createdAt: new Date().toISOString(),
+          lastUsedAt: new Date().toISOString(),
+          transports: attachment === 'cross-platform' ? ['usb', 'nfc'] : ['internal', 'hybrid'],
+          attachment: attachment || 'platform',
+          signCount: 1,
+          backedUp: attachment !== 'cross-platform',
+          alg: 'ES256 (-7)',
+          rpId,
+          source: 'Virtual WebAuthn Passkey'
+        };
