+
+      /**
+       * Requests a WebAuthn assertion via `navigator.credentials.get`
+       * and verifies/updates the matched passkey counter & timestamp.
+       */
+      async function assertPasskeyCredential({ user, preferredCredentialId }) {
+        const challenge = generateRandomBytes(32);
+        const rpId = getEffectiveRpId();
+
+        let allowCredentials = [];
+        if (user && user.passkeys && user.passkeys.length > 0) {
+          const targetList = preferredCredentialId
+            ? user.passkeys.filter((pk) => pk.id === preferredCredentialId)
+            : user.passkeys;
+
+          allowCredentials = targetList.map((pk) => ({
+            id: base64UrlToBuffer(pk.id),
+            type: 'public-key',
+            transports: pk.transports || ['internal']
+          }));
+        }
+
+        const publicKeyCredentialRequestOptions = {
+          challenge,
+          rpId,
+          timeout: 60000,
+          userVerification: 'required',
+          ...(allowCredentials.length > 0 ? { allowCredentials } : {})
+        };
+
+        const preferVirtual = state.useVirtualAuthenticator || !isNativeWebAuthnAvailable();
+
+        if (!preferVirtual) {
+          try {
+            const assertion = await navigator.credentials.get({
+              publicKey: publicKeyCredentialRequestOptions
+            });
+            if (assertion && assertion.rawId) {
+              const assertedId = bufferToBase64Url(assertion.rawId);
+              const matched = findUserAndPasskeyByCredentialId(assertedId, user);
+              if (matched) {
+                matched.passkey.signCount = (matched.passkey.signCount || 0) + 1;
+                matched.passkey.lastUsedAt = new Date().toISOString();
+                return matched;
+              }
+            }
+          } catch (nativeErr) {
+            console.warn('Native WebAuthn assertion fell back to Virtual Passkey Authenticator:', nativeErr);
+          }
+        }
