+        // Virtual Authenticator Assertion Resolution
+        if (user) {
+          if (!user.passkeys || user.passkeys.length === 0) {
+            throw new Error('No saved passkeys are registered for this customer account.');
+          }
+          const chosenPasskey =
+            (preferredCredentialId && user.passkeys.find((p) => p.id === preferredCredentialId)) ||
+            user.passkeys[0];
+          chosenPasskey.signCount = (chosenPasskey.signCount || 0) + 1;
+          chosenPasskey.lastUsedAt = new Date().toISOString();
+          return { user, passkey: chosenPasskey };
+        }
