+        // Discoverable credential lookup across all registered accounts
+        const userWithPasskey = state.users.find((u) => u.passkeys && u.passkeys.length > 0);
+        if (!userWithPasskey) {
+          throw new Error('No discoverable passkeys found. Please register a customer account first.');
+        }
+        const passkey = userWithPasskey.passkeys[0];
+        passkey.signCount = (passkey.signCount || 0) + 1;
+        passkey.lastUsedAt = new Date().toISOString();
+        return { user: userWithPasskey, passkey };
+      }
+
+      function findUserAndPasskeyByCredentialId(credId, fallbackUser) {
+        for (const u of state.users) {
+          const pk = (u.passkeys || []).find((p) => p.id === credId);
+          if (pk) return { user: u, passkey: pk };
+        }
+        if (fallbackUser && fallbackUser.passkeys && fallbackUser.passkeys.length > 0) {
+          return { user: fallbackUser, passkey: fallbackUser.passkeys[0] };
+        }
+        return null;
+      }
+
+      // --- Helper Functions for State & UI ---
