+                  ? 'opacity-75 cursor-not-allowed'
+                  : ''
+              }`}
+            >
+              <FingerPrintIcon className="w-5 h-5 text-amber-400" />
+              <span>
+                {passkeyLoading ? 'Creating Passkey...' : 'Sign Up with a Passkey'}
+              </span>
+            </button>
+          </>
+        ) : (
+          <>
+            <div>
+              <label
+                htmlFor="password"
+                className="block text-sm font-medium text-gray-700 mb-1"
+              >
+                Password
+              </label>
+              <input
+                type="password"
+                id="password"
+                name="password"
+                autoComplete="new-password"
+                value={password}
+                onChange={(e) => setPassword(e.target.value)}
+                required
+                className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
+              />
+              <p className="text-xs text-gray-500 mt-1">
+                Must be at least 8 characters and contain a number.
+              </p>
+            </div>
+
+            <button
+              type="submit"
+              disabled={loading || passkeyLoading}
+              data-skip-tracking="true"
+              className={`w-full py-2 px-4 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-gray-900 hover:bg-gray-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-900 ${
+                loading ? 'opacity-75 cursor-not-allowed' : ''
+              }`}
+            >
+              {loading ? 'Signing up...' : 'Sign Up with Password'}
+            </button>
+
+            <div className="pt-2 text-center">
+              <button
+                type="button"
+                onClick={() => handlePasskeyRegistration()}
+                disabled={passkeyLoading || loading || !capabilities.isSupported}
+                className="text-xs font-medium text-gray-700 hover:text-gray-900 inline-flex items-center gap-1 hover:underline"
+              >
+                <FingerPrintIcon className="w-4 h-4 text-amber-500" />
+                Or register instantly with a passkey instead
+              </button>
+            </div>
+          </>
+        )}
       </form>
+
+      <div className="mt-6 pt-4 border-t border-gray-100 flex items-center justify-between text-xs text-gray-600">
+        <span>
+          Already have an account?{' '}
+          <a
+            href={`${baseUrl}signin`}
+            className="font-semibold text-gray-900 hover:underline"
+          >
+            Sign in
+          </a>
+        </span>
+        <a
+          href={`${baseUrl}account`}
+          className="font-medium text-gray-700 hover:text-gray-900 hover:underline"
+        >
+          Account Settings
+        </a>
+      </div>
     </div>
   );
 }
