+import type { APIRoute } from 'astro';
+import crypto from 'node:crypto';
+
+export const POST: APIRoute = async ({ request, session }) => {
+  const body = await request.json().catch(() => ({}));
+  const challenge = crypto.randomBytes(32).toString('base64url');
+  const username = body.username || 'alex.mercer';
+  const displayName = body.displayName || username;
+  const userId = body.userId || `usr_${Buffer.from(username).toString('base64url').slice(0, 16)}`;
+
+  if (session) {
+    await session.set('webauthn_register_challenge', challenge);
+  }
+
+  return new Response(
+    JSON.stringify({
+      challenge,
+      rp: {
+        name: 'The DevTools Times',
+      },
+      user: {
+        id: Buffer.from(userId).toString('base64url'),
+        name: username,
+        displayName,
+      },
+      pubKeyCredParams: [
+        { alg: -7, type: 'public-key' },
+        { alg: -257, type: 'public-key' },
+        { alg: -8, type: 'public-key' },
+      ],
+      timeout: 60000,
+      attestation: 'none',
+      authenticatorSelection: {
+        residentKey: 'required',
+        requireResidentKey: true,
+        userVerification: 'required',
+      },
+    }),
+    {
+      status: 200,
+      headers: { 'Content-Type': 'application/json' },
+    }
+  );
+};
