+/**
+ * The Daily Grind — Privacy-by-Design Client-Side Script
+ *
+ * Implements:
+ * 1. Trusted Types policy for safe DOM operations & avoiding raw innerHTML sinks.
+ * 2. PII log scrubbing & sliding-window client rate limiting on sensitive actions.
+ * 3. Secure state management (in-memory transient state; zero sensitive tokens or PII in localStorage).
+ * 4. Differential Privacy (Laplace/randomized noise fuzzing) for aggregate seasonal drink statistics.
+ * 5. Feature Detection & User-Agent Client Hints (UA-CH) without covert fingerprinting or navigator.userAgent sniffing.
+ * 6. Page Embedded Permission Control (<permission type="geolocation">) & explicit context-first geolocation fallback.
+ * 7. Third-Party Audits & Mitigations:
+ *    - Video Façade Pattern loading youtube-nocookie.com only upon explicit click.
+ *    - Federated Credential Management API (FedCM) native sign-in flow.
+ *    - Network & Subresource Security Audit inspector using PerformanceResourceTiming & CSS.supports().
+ * 8. Data Minimization, Ephemeral Order Fulfillment Deletion, and Logout via Clear-Site-Data subresource.
+ * 9. User Data Rights (Access, Correction, and Instant Self-Service Account/Data Deletion).
+ */
+
+import { scrubLogPII } from './security-headers.js';
+
+// 1. Trusted Types Policy for DOM XSS prevention
+const htmlPolicy =
+  typeof window !== 'undefined' && window.trustedTypes?.createPolicy
+    ? window.trustedTypes.createPolicy('daily-grind-html', {
+        createHTML(input) {
+          return String(input)
+            .replace(/&/g, '&amp;')
+            .replace(/</g, '&lt;')
+            .replace(/>/g, '&gt;')
+            .replace(/"/g, '&quot;')
+            .replace(/'/g, '&#39;');
+        },
+        createScriptURL(url) {
+          const parsed = new URL(url, window.location.origin);
+          const allowedOrigins = new Set([
+            window.location.origin,
+            'https://www.youtube-nocookie.com',
+          ]);
+          if (!allowedOrigins.has(parsed.origin)) {
+            throw new TypeError(`Blocked untrusted script URL origin: ${parsed.origin}`);
+          }
+          return parsed.href;
+        },
+      })
+    : null;
+
+/**
+ * Privacy-safe logger that scrubs emails, tokens, phones, and IDs before logging.
+ */
+export function logPrivacySafe(eventLabel, details = {}) {
