+    // Harden all anchor links
+    const links = document.querySelectorAll('a[href]');
+    links.forEach((link) => {
+      try {
+        const url = new URL(link.href, window.location.origin);
+        if (url.origin !== window.location.origin || link.target === '_blank') {
+          link.setAttribute('rel', 'noopener noreferrer');
+          link.setAttribute('referrerpolicy', 'no-referrer');
+        }
+      } catch (_) {
+        // Ignore non-standard hrefs
+      }
+    });
+
+    // Update Audit UI safely using textContent
+    const mediaStatusEl = document.getElementById('audit-media-status');
+    const scriptsStatusEl = document.getElementById('audit-scripts-status');
