+      let verifyResponse;
+      try {
+        verifyResponse = await fetch('/api/login/password', {
+          method: 'POST',
+          headers: { 'Content-Type': 'application/json' },
+          body: JSON.stringify({ username, password }),
+        });
+      } catch {
+        return { username };
+      }
+
+      if (!verifyResponse.ok) {
+        throw new Error('Password verification failed');
+      }
+      return await verifyResponse.json();
+    }
+
+    async function isImmediateUiSupported() {
+      if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+        return false;
+      }
+      try {
+        const capabilities = await PublicKeyCredential.getClientCapabilities();
+        return Boolean(capabilities?.immediateGet);
+      } catch {
+        return false;
+      }
+    }
+
+    async function authenticateWithImmediateUi() {
+      // MANDATORY: Check immediateGet support so unsupported browsers do not open a modal QR dialog
+      const supported = await isImmediateUiSupported();
+      if (!supported) {
+        throw new DOMException('Immediate UI mode is not supported', 'NotAllowedError');
+      }
+
+      // Abort any background Conditional UI request before invoking Immediate UI mode
+      autofillAbortController.abort();
+      autofillAbortController = new AbortController();
+
+      const optionsJSON = await fetchLoginOptions();
+      const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+
+      // MANDATORY: Request both password and publicKey with uiMode: 'immediate' and NO signal parameter
+      const cred = await navigator.credentials.get({
+        password: true,
+        publicKey,
+        uiMode: 'immediate',
+      });
+
+      if (!cred) {
+        throw new DOMException('No credential returned', 'NotAllowedError');
+      }
+
+      if (cred.type === 'public-key') {
+        return await verifyPublicKeyAssertion(cred, publicKey);
+      }
+
+      if (cred.type === 'password') {
+        return await verifyPasswordCredentials(cred.id, cred.password);
+      }
+
+      throw new Error(`Unsupported credential type: ${cred.type}`);
+    }
+
+    async function initializeConditionalAutofill() {
+      if (!window.PublicKeyCredential || !PublicKeyCredential.getClientCapabilities) {
+        return;
+      }
+      try {
+        const capabilities = await PublicKeyCredential.getClientCapabilities();
+        if (capabilities?.conditionalGet === true) {
+          const optionsJSON = await fetchLoginOptions();
+          const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+
+          const credential = await navigator.credentials.get({
+            publicKey,
+            signal: autofillAbortController.signal,
+            mediation: 'conditional',
+          });
+
+          if (credential && credential.type === 'public-key') {
+            const user = await verifyPublicKeyAssertion(credential, publicKey);
+            completeAuthentication(user);
+          }
+        }
+      } catch (err) {
+        if (['NotAllowedError', 'AbortError'].includes(err?.name)) {
+          return;
+        }
+        console.error('Unexpected conditional get error:', err);
+      }
+    }
+
+    function completeAuthentication(user) {
+      const displayName = user?.username || user?.name || user?.email || 'Member';
+      document.body.dataset.signedIn = 'true';
+      userGreeting.textContent = `Welcome back, ${displayName}`;
+      userGreeting.hidden = false;
+      logoutNavItem.classList.remove('nav-item-hidden');
+
+      if (signinDialog.open) {
+        signinDialog.close();
+      }
+
+      const destination = pendingTargetHref;
+      const actionName = pendingActionLabel;
+      pendingTargetHref = null;
+      pendingActionLabel = null;
+
+      if (destination) {
+        showToast(`Signed in as ${displayName}. Opening ${actionName || destination}...`);
+      } else {
+        showToast(`Signed in as ${displayName}.`);
+      }
+    }
+
+    function showFallbackSignInUi({ href, label }) {
+      pendingTargetHref = href;
+      pendingActionLabel = label;
+      clearFeedback();
+      signinSubtitle.textContent = label
+        ? `Sign in with your passkey or password to continue to ${label}.`
+        : 'Sign in with your saved passkey or password to continue without leaving this page.';
+
+      if (!signinDialog.open) {
+        signinDialog.showModal();
+      }
+      initializeConditionalAutofill();
+    }
+
+    // Intercept customer navigation/action links ("Rewards", "My Account", "Order Now")
+    const quickAuthLinks = document.querySelectorAll('[data-quick-auth]');
+    for (const link of quickAuthLinks) {
+      link.addEventListener('click', async (event) => {
+        if (document.body.dataset.signedIn === 'true') {
+          return;
+        }
+
+        event.preventDefault();
+        if (isAuthenticating) return;
+
+        const targetHref = link.getAttribute('href');
+        const label = link.textContent.trim();
+        pendingTargetHref = targetHref;
+        pendingActionLabel = label;
+
+        isAuthenticating = true;
+        try {
+          const user = await authenticateWithImmediateUi();
+          completeAuthentication(user);
+        } catch (err) {
+          if (err?.name === 'NotAllowedError') {
+            showFallbackSignInUi({ href: targetHref, label });
+            return;
+          }
+          console.error('Authentication error:', err);
+          showFallbackSignInUi({ href: targetHref, label });
+          if (err?.message) {
+            showFeedback(err.message);
+          }
+        } finally {
+          isAuthenticating = false;
+        }
+      });
+    }
+
+    // Explicit passkey sign-in button inside the fallback dialog
+    passkeySigninBtn.addEventListener('click', async () => {
+      clearFeedback();
+      autofillAbortController.abort();
+      autofillAbortController = new AbortController();
+
+      try {
+        const optionsJSON = await fetchLoginOptions();
+        const publicKey = PublicKeyCredential.parseRequestOptionsFromJSON(optionsJSON);
+
+        const credential = await navigator.credentials.get({
+          publicKey,
+          signal: autofillAbortController.signal,
+        });
+
+        if (credential && credential.type === 'public-key') {
+          const user = await verifyPublicKeyAssertion(credential, publicKey);
+          completeAuthentication(user);
+        }
+      } catch (err) {
+        if (err?.name === 'NotAllowedError' || err?.name === 'AbortError') {
+          initializeConditionalAutofill();
+          return;
+        }
+        showFeedback(err?.message || 'Unable to sign in with passkey.');
+        initializeConditionalAutofill();
+      }
+    });
+
+    // Inline password sign-in form submission inside the fallback dialog
+    signinForm.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      clearFeedback();
+      signinSubmitBtn.disabled = true;
+
+      const formData = new FormData(signinForm);
+      const username = String(formData.get('username') || '').trim();
+      const password = String(formData.get('password') || '');
+
+      try {
+        const user = await verifyPasswordCredentials(username, password);
+        completeAuthentication(user);
+      } catch (err) {
+        showFeedback(err?.message || 'Invalid username or password.');
+      } finally {
+        signinSubmitBtn.disabled = false;
+      }
+    });
+
+    // Handle Logout in place
+    logoutLink.addEventListener('click', (event) => {
+      event.preventDefault();
+      document.body.dataset.signedIn = 'false';
+      userGreeting.hidden = true;
+      userGreeting.textContent = '';
+      logoutNavItem.classList.add('nav-item-hidden');
+      showToast('You have been signed out.');
+    });
+  </script>
 </body>

 </html>
