+    emailInput.addEventListener('input', () => {
+      emailInput.setCustomValidity('');
+      emailInput.removeAttribute('aria-invalid');
+      if (statusEl.dataset.state === 'error') {
+        setStatusMessage('', '');
+      }
+    });
+
+    form.addEventListener('submit', async (event) => {
+      event.preventDefault();
+      if (!validateEmailField()) {
+        emailInput.focus();
+        return;
+      }
+
+      const email = emailInput.value.trim();
+      const endpoint = form.getAttribute('action') || '/api/newsletter';
+
+      submitBtn.disabled = true;
+      try {
+        const result = await fetchWithPolicyHandling(endpoint, {
+          statusElement: statusEl,
+          method: 'POST',
+          headers: {
+            'Content-Type': 'application/json',
+            Accept: 'application/json',
+          },
+          body: JSON.stringify({ email }),
+        });
+
+        if (result.ok) {
+          form.reset();
+        }
+      } finally {
+        submitBtn.disabled = false;
+      }
+    });
+
+    document.addEventListener('securitypolicyviolation', (event) => {
+      const blockedTarget = event.blockedURI || event.violatedDirective || 'an external server';
+      setStatusMessage(
+        `⚠ Security policy blocked an unauthorized request to ${blockedTarget}. Your data was not sent.`,
+        'error',
+      );
+    });
+  </script>
+
 </body>

