+
+      const currentOrder = cardEl.dataset.sortOrder === 'asc' ? 'desc' : 'asc';
+      cardEl.dataset.sortOrder = currentOrder;
+
+      const sortedIds = Array.from(listEl.children)
+        .sort((a, b) => {
+          const priceA = Number.parseFloat(a.dataset.price || '0');
+          const priceB = Number.parseFloat(b.dataset.price || '0');
+          return currentOrder === 'asc' ? priceA - priceB : priceB - priceA;
