+
+    function syncCouponRevealedState() {
+      couponPanel.removeAttribute('hidden');
+      revealBtn.setAttribute('aria-expanded', 'true');
+      revealBtn.setAttribute('aria-disabled', 'true');
+      revealBtn.textContent = 'Coupon Revealed';
+    }
+
+    // Invoker Commands API fallback if CommandEvent is not natively supported
+    if (!globalThis.CommandEvent) {
+      globalThis.CommandEvent = class CommandEvent extends Event {
+        constructor(type, { source, command, ...options } = {}) {
+          super(type, options);
+          this.source = source;
+          this.command = command;
+        }
+      };
+
+      document.addEventListener('click', (event) => {
+        const button = event.composedPath().find((el) => el.matches?.('button[commandfor]'));
+        if (!button) return;
+
+        const target = document.getElementById(button.getAttribute('commandfor'));
+        const command = button.getAttribute('command');
+
+        if (target && command) {
+          target.dispatchEvent(new CommandEvent('command', {
+            command,
+            source: button,
+          }));
+        }
+      });
+    }
+
+    // Listen for the custom command directly on #coupon-panel (does not bubble)
