+          // Cold deep-link start: pop to parent route in stack and sync URL
+          const parentStack = currentStack.slice(0, currentStack.length - 1);
+          const parentEntry = parentStack[parentStack.length - 1];
+          pushUrlState(parentEntry.path, parentStack);
+          applyStackState(parentStack);
+        }
+      }
+
+      function navigateToStackLevel(targetLevel) {
+        const activeDepth = currentStack.length - 1;
+        if (targetLevel < 0 || targetLevel >= activeDepth) return;
+        const stepsBack = activeDepth - targetLevel;
+        if (stepsBack === 1) {
+          navigateBack();
+        } else if (inAppHistoryCount >= stepsBack) {
+          inAppHistoryCount -= stepsBack;
+          window.history.go(-stepsBack);
+        } else {
+          const targetEntry = currentStack[targetLevel];
+          navigateToPath(targetEntry.path);
+        }
+      }
+
+      /* Browser Back / Forward / Hashchange Listeners */
+      window.addEventListener('popstate', function () {
+        const nextStack = parseLocationToStack(window.location);
+        applyStackState(nextStack);
+      });
+
+      window.addEventListener('hashchange', function () {
+        const nextStack = parseLocationToStack(window.location);
+        applyStackState(nextStack);
+      });
+
+      /* ==========================================================================
+       * Interactive Touch & Pointer Horizontal Swipe-Back Gesture
+       * ========================================================================== */
+      let swipeState = {
+        tracking: false,
+        dragging: false,
+        startX: 0,
+        startY: 0,
+        currentX: 0,
+        startTime: 0,
+        pointerId: null
+      };
+
+      function getActiveScreenElements() {
+        const activeDepth = currentStack.length - 1;
+        if (activeDepth <= 0) return null;
+        const screens = [screenHomeEl, screenDetailEl, screenSubdetailEl];
+        return {
+          active: screens[activeDepth],
+          previous: screens[activeDepth - 1]
+        };
+      }
+
+      function beginSwipeTrack(clientX, clientY, fromEdgeZone) {
+        if (currentStack.length <= 1) return false;
+        // Allow swipe from anywhere on detail view, or immediate drag from left edge zone
+        swipeState.tracking = true;
+        swipeState.dragging = Boolean(fromEdgeZone);
+        swipeState.startX = clientX;
+        swipeState.startY = clientY;
+        swipeState.currentX = clientX;
+        swipeState.startTime = Date.now();
+        if (swipeState.dragging) {
+          viewportEl.classList.add('is-dragging');
+        }
+        return true;
+      }
+
+      function moveSwipeTrack(clientX, clientY) {
+        if (!swipeState.tracking) return;
+        const dx = clientX - swipeState.startX;
+        const dy = clientY - swipeState.startY;
+
+        if (!swipeState.dragging) {
+          // Only lock into horizontal swipe-back when moving right more than vertically
+          if (dx > 14 && Math.abs(dx) > Math.abs(dy) * 1.25) {
+            swipeState.dragging = true;
+            viewportEl.classList.add('is-dragging');
+          } else if (Math.abs(dy) > 18 && Math.abs(dy) > Math.abs(dx)) {
+            swipeState.tracking = false;
+            return;
+          } else {
+            return;
+          }
+        }
+
+        swipeState.currentX = clientX;
+        const clampedDx = Math.max(0, dx);
+        const width = viewportEl.clientWidth || window.innerWidth || 375;
+        const progress = Math.min(1, clampedDx / width);
+
+        const pair = getActiveScreenElements();
+        if (!pair) return;
+
+        pair.active.style.transform = `translate3d(${clampedDx}px, 0, 0)`;
+        const prevOffset = -26 * (1 - progress);
+        const prevScale = 0.985 + 0.015 * progress;
+        const prevBrightness = 0.72 + 0.28 * progress;
+        pair.previous.style.transform = `translate3d(${prevOffset}%, 0, 0) scale(${prevScale})`;
+        pair.previous.style.filter = `brightness(${prevBrightness})`;
+      }
+
+      function endSwipeTrack() {
+        if (!swipeState.tracking) return;
+        const wasDragging = swipeState.dragging;
+        const dx = swipeState.currentX - swipeState.startX;
+        const elapsed = Math.max(1, Date.now() - swipeState.startTime);
+        const velocity = dx / elapsed; // px per ms
+        const width = viewportEl.clientWidth || window.innerWidth || 375;
+
+        swipeState.tracking = false;
+        swipeState.dragging = false;
+        viewportEl.classList.remove('is-dragging');
+
+        const pair = getActiveScreenElements();
+        if (pair) {
+          pair.active.style.transform = '';
+          pair.previous.style.transform = '';
+          pair.previous.style.filter = '';
+        }
+
+        if (wasDragging && (dx > width * 0.24 || (dx > 45 && velocity > 0.45))) {
+          navigateBack();
+        }
+      }
+
+      // Touch events for mobile/tablet swipe-back
+      viewportEl.addEventListener('touchstart', function (e) {
+        if (e.touches.length !== 1) return;
+        const touch = e.touches[0];
+        beginSwipeTrack(touch.clientX, touch.clientY, touch.clientX <= 36);
+      }, { passive: true });
+
+      viewportEl.addEventListener('touchmove', function (e) {
+        if (!swipeState.tracking || e.touches.length !== 1) return;
+        const touch = e.touches[0];
+        moveSwipeTrack(touch.clientX, touch.clientY);
+      }, { passive: true });
+
+      viewportEl.addEventListener('touchend', function () {
+        endSwipeTrack();
+      });
+
+      viewportEl.addEventListener('touchcancel', function () {
+        endSwipeTrack();
+      });
+
+      // Pointer/Mouse drag support (from edge zone or horizontal drag on detail background)
+      edgeSwipeZone.addEventListener('mousedown', function (e) {
+        e.preventDefault();
+        beginSwipeTrack(e.clientX, e.clientY, true);
+      });
+
+      viewportEl.addEventListener('mousedown', function (e) {
+        if (currentStack.length <= 1) return;
+        if (e.button !== 0) return;
+        // Avoid interfering with buttons/links unless dragging
+        if (e.target.closest('button, a, input, select, textarea')) return;
+        beginSwipeTrack(e.clientX, e.clientY, e.clientX <= 36);
+      });
+
+      window.addEventListener('mousemove', function (e) {
+        if (!swipeState.tracking) return;
+        moveSwipeTrack(e.clientX, e.clientY);
+      });
+
+      window.addEventListener('mouseup', function () {
+        if (!swipeState.tracking) return;
+        endSwipeTrack();
+      });
+
+      /* ==========================================================================
+       * Event Delegation for Cards, Drill-Down Links, Back Buttons & Customizer
+       * ========================================================================== */
+      document.addEventListener('click', function (e) {
+        // 1. Back button clicks
+        const backBtn = e.target.closest('[data-action="back"]');
+        if (backBtn) {
+          e.preventDefault();
+          navigateBack();
+          return;
+        }
+
+        // 2. Root logo / home links
+        const rootLink = e.target.closest('[data-nav-root]');
+        if (rootLink) {
+          e.preventDefault();
+          if (currentStack.length > 1) {
+            navigateToStackLevel(0);
+          }
+          return;
+        }
+
+        // 3. Breadcrumb hierarchy jumps
+        const crumbLink = e.target.closest('[data-crumb-level]');
+        if (crumbLink) {
+          e.preventDefault();
+          const targetLevel = parseInt(crumbLink.getAttribute('data-crumb-level'), 10);
+          navigateToStackLevel(targetLevel);
+          return;
+        }
+
+        // 4. Level 2 subview drill-down cards
+        const subviewLink = e.target.closest('[data-drill-subview]');
+        if (subviewLink) {
+          e.preventDefault();
+          const parentSlug = subviewLink.getAttribute('data-parent-slug');
+          const subview = subviewLink.getAttribute('data-drill-subview');
+          if (ITEMS[parentSlug] && SUBVIEWS.includes(subview)) {
+            navigateToPath(ITEMS[parentSlug].path + '/' + subview);
+          }
+          return;
+        }
+
+        // 5. Seasonal Favorites "View Details" link or related item card
+        const drillLink = e.target.closest('[data-drill-link]');
+        if (drillLink) {
+          e.preventDefault();
+          const slug = drillLink.getAttribute('data-drill-link');
+          if (ITEMS[slug]) {
+            navigateToPath(ITEMS[slug].path);
+          }
+          return;
+        }
+
+        // 6. Clicking anywhere on a Seasonal Favorites card on Home screen
+        const cardEl = e.target.closest('.card[data-item-slug]');
+        if (cardEl) {
+          e.preventDefault();
+          const slug = cardEl.getAttribute('data-item-slug');
+          if (ITEMS[slug]) {
+            navigateToPath(ITEMS[slug].path);
+          }
+          return;
+        }
+
+        // 7. Scroll to Seasonal Favorites CTA on Home
+        const scrollSeasonal = e.target.closest('[data-scroll-seasonal]');
+        if (scrollSeasonal) {
+          e.preventDefault();
+          if (currentStack.length > 1) {
+            navigateToStackLevel(0);
+          }
+          const section = document.getElementById('seasonal-favorites-section');
+          if (section) {
+            section.scrollIntoView({ behavior: 'smooth' });
+          }
+          return;
+        }
+
+        // 8. Size & Milk customization pills inside Detail View
+        const sizePill = e.target.closest('.option-pill[data-size]');
+        if (sizePill) {
+          selectedCustomizations.size = sizePill.getAttribute('data-size');
+          selectedCustomizations.sizeDelta = parseFloat(sizePill.getAttribute('data-delta') || '0');
+          const activeSlug = screenDetailEl.getAttribute('data-active-slug');
+          if (activeSlug) renderDetailScreen(activeSlug);
+          return;
+        }
+
+        const milkPill = e.target.closest('.option-pill[data-milk]');
+        if (milkPill) {
+          selectedCustomizations.milk = milkPill.getAttribute('data-milk');
+          const activeSlug = screenDetailEl.getAttribute('data-active-slug');
+          if (activeSlug) renderDetailScreen(activeSlug);
+          return;
+        }
+
+        // 9. Add to Order button
+        const addBtn = e.target.closest('#add-to-order-btn');
+        if (addBtn) {
+          cartCount += 1;
+          cartCountEl.textContent = String(cartCount);
+          const activeSlug = screenDetailEl.getAttribute('data-active-slug');
+          const item = ITEMS[activeSlug];
+          const feedbackEl = document.getElementById('order-feedback');
+          if (feedbackEl && item) {
+            feedbackEl.textContent = `Added ${selectedCustomizations.size} ${item.title} (${selectedCustomizations.milk}) to your cup!`;
+          }
+          return;
+        }
+      });
+
+      // Copy Deep Link button
+      if (copyDeeplinkBtn) {
+        copyDeeplinkBtn.addEventListener('click', function () {
+          const url = window.location.href;
+          if (navigator.clipboard && navigator.clipboard.writeText) {
+            navigator.clipboard.writeText(url).catch(function () {});
+          }
+          copyDeeplinkBtn.textContent = 'Link Copied!';
+          setTimeout(function () {
+            copyDeeplinkBtn.textContent = 'Copy Link';
+          }, 1800);
+        });
+      }
+
+      // Keyboard navigation support (Enter/Space on cards, Escape to pop stack)
+      document.addEventListener('keydown', function (e) {
+        if (e.key === 'Escape' && currentStack.length > 1) {
+          e.preventDefault();
+          navigateBack();
+          return;
+        }
+        if ((e.key === 'Enter' || e.key === ' ') && document.activeElement) {
+          const focusedCard = document.activeElement.closest('.card[data-item-slug]');
+          if (focusedCard && document.activeElement === focusedCard) {
+            e.preventDefault();
+            const slug = focusedCard.getAttribute('data-item-slug');
+            if (ITEMS[slug]) {
+              navigateToPath(ITEMS[slug].path);
+            }
+          }
+        }
+      });
+
+      /* ==========================================================================
+       * Initial Boot & Deep-Link Synchronization
+       * ========================================================================== */
+      const initialStack = parseLocationToStack(window.location);
+      const initialTop = initialStack[initialStack.length - 1];
+      replaceUrlState(initialTop.path, initialStack);
+      applyStackState(initialStack, { scrollTopLevel: initialStack.length - 1 });
+
+      // Expose navigation stack controller for programmatic inspection if needed
+      window.DailyGrindStack = {
+        getStack: function () { return currentStack.slice(); },
+        navigateTo: navigateToPath,
+        back: navigateBack
+      };
+    })();
+  </script>
