+            className="p-2 rounded-md border border-gray-300 bg-white text-gray-700 hover:bg-gray-100 hover:text-gray-900 transition-colors"
+          >
+            <ArrowsRightLeftIcon className="w-4 h-4" aria-hidden="true" />
+            <span className="sr-only">Swap source and target languages</span>
+          </button>
+
+          <div>
+            <label
+              htmlFor={targetSelectId}
+              className="block text-xs font-semibold text-gray-700 mb-1"
+            >
+              To language
+            </label>
+            <select
+              id={targetSelectId}
+              value={targetLanguage}
+              onChange={(e) => handleTargetLanguageChange(e.target.value)}
+              disabled={isTranslating}
+              className="w-full rounded-md border border-gray-300 bg-white px-2.5 py-1.5 text-sm text-gray-900 focus:border-amber-500 focus:outline-none"
+            >
+              {SUPPORTED_LANGUAGES.map((lang) => (
+                <option key={lang.code} value={lang.code}>
+                  {lang.name} ({lang.nativeName})
+                </option>
+              ))}
+            </select>
+          </div>
+        </div>
+
+        <div className="flex items-center gap-2 shrink-0">
+          <button
+            type="button"
+            onClick={handleTranslate}
+            disabled={isTranslateDisabled}
+            aria-describedby={!apiSupported ? statusId : undefined}
+            className="inline-flex items-center justify-center gap-1.5 rounded-md bg-gray-900 px-4 py-2 text-sm font-semibold text-white hover:bg-gray-800 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
+          >
+            {isTranslating ? (
+              <>
+                <ArrowPathIcon
+                  className="w-4 h-4 animate-spin"
+                  aria-hidden="true"
+                />
+                <span>Translating…</span>
+              </>
+            ) : (
+              <>
+                <LanguageIcon className="w-4 h-4" aria-hidden="true" />
+                <span>Translate Article</span>
+              </>
+            )}
+          </button>
+
+          {isTranslated && (
+            <button
+              type="button"
+              onClick={handleRestoreOriginal}
+              disabled={isTranslating}
+              className="inline-flex items-center justify-center rounded-md border border-gray-300 bg-white px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-100 transition-colors"
+            >
+              Show Original
+            </button>
+          )}
+        </div>
+      </div>
+
+      {isTranslating && (
+        <div className="mt-3">
+          <progress
+            className="w-full h-2 rounded overflow-hidden"
+            value={
+              downloadProgress !== null
+                ? downloadProgress
+                : elementsProgress && elementsProgress.total > 0
+                  ? Math.round(
+                      (elementsProgress.completed / elementsProgress.total) *
+                        100,
+                    )
+                  : undefined
+            }
+            max={100}
+          />
+          <p className="text-xs text-gray-600 mt-1">
+            {downloadProgress !== null
+              ? `Downloading on-device language pack (${downloadProgress}%)…`
+              : elementsProgress
+                ? `Translating article sections (${elementsProgress.completed} of ${elementsProgress.total})…`
+                : 'Starting on-device translation…'}
+          </p>
+        </div>
+      )}
+
+      {!apiSupported && (
+        <p
+          id={statusId}
+          className="mt-3 text-xs text-amber-800 bg-amber-50 border border-amber-200 rounded p-2"
+        >
+          Client-side translation is currently unsupported in this browser. To
+          translate articles on-device, open The DevTools Times in Chrome 138+
+          or Edge 148+ on desktop.
+        </p>
+      )}
+
+      {sourceLanguage === targetLanguage && apiSupported && (
+        <p className="mt-2 text-xs text-gray-500">
+          Select two different languages to translate this article.
+        </p>
+      )}
+
+      {errorMessage && (
+        <p
+          role="alert"
+          className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded p-2"
+        >
+          {errorMessage}
+        </p>
+      )}
+
+      {statusMessage && !errorMessage && (
+        <div
+          aria-live="polite"
+          className="mt-3 text-xs text-emerald-800 bg-emerald-50 border border-emerald-200 rounded p-2 flex items-center justify-between gap-2"
+        >
+          <span className="flex items-center gap-1.5">
+            <CheckCircleIcon
+              className="w-4 h-4 text-emerald-600 shrink-0"
+              aria-hidden="true"
+            />
+            {statusMessage}
+          </span>
+          {isTranslated && (
+            <button
+              type="button"
+              onClick={handleRestoreOriginal}
+              className="font-semibold underline hover:text-emerald-950"
+            >
+              Restore original
+            </button>
+          )}
+        </div>
+      )}
+    </div>
+  );
+}
