+
+function fallbackLocalTranslate(text: string, sourceLanguage: string, targetLanguage: string): string {
+  const trimmed = text.trim();
+  if (!trimmed || sourceLanguage === targetLanguage) return text;
+
+  const dict = OFFLINE_DICTIONARY[targetLanguage];
+  if (dict) {
+    if (dict[trimmed]) {
+      return text.replace(trimmed, dict[trimmed]);
+    }
+    // Word-level phrasebook substitution when exact headline/phrase isn't matched
+    const words = trimmed.split(/(\s+|[.,!?;:"'()—-]+)/);
+    let replacedCount = 0;
+    const translatedWords = words.map((token) => {
+      const lower = token.toLowerCase();
+      if (dict[lower]) {
+        replacedCount++;
+        const replacement = dict[lower];
+        if (token[0] && token[0] === token[0].toUpperCase() && token[0] !== token[0].toLowerCase()) {
+          return replacement.charAt(0).toUpperCase() + replacement.slice(1);
+        }
+        return replacement;
+      }
+      return token;
+    });
+    if (replacedCount > 0) {
+      return translatedWords.join('');
+    }
+  }
+
+  return `[${targetLanguage.toUpperCase()}] ${trimmed}`;
+}
+
+const textTranslationMemory = new Map<string, string>();
+
+export async function translateTextOnDevice(
+  text: string,
+  options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal?: AbortSignal;
+    onDownloadProgress?: (pct: number) => void;
+  }
+): Promise<{ translatedText: string; usedNativeApi: boolean }> {
+  const { sourceLanguage, targetLanguage, signal, onDownloadProgress } = options;
+  const trimmed = text.trim();
+  if (!trimmed || sourceLanguage === targetLanguage) {
+    return { translatedText: text, usedNativeApi: true };
+  }
+
+  const memKey = `${sourceLanguage}:${targetLanguage}:${trimmed}`;
+  if (textTranslationMemory.has(memKey)) {
+    return { translatedText: textTranslationMemory.get(memKey)!, usedNativeApi: true };
+  }
+
+  const translator = await getOrCreateOnDeviceTranslator({
+    sourceLanguage,
+    targetLanguage,
+    signal,
+    onDownloadProgress,
+  });
+
+  if (translator) {
+    try {
+      const result = await translator.translate(trimmed, { signal });
+      textTranslationMemory.set(memKey, result);
+      return { translatedText: result, usedNativeApi: true };
+    } catch (err) {
+      if ((err as Error)?.name === 'AbortError') throw err;
+      console.warn('Translator.translate error, using local fallback:', err);
+    }
+  }
+
+  const fallbackResult = fallbackLocalTranslate(text, sourceLanguage, targetLanguage);
+  textTranslationMemory.set(memKey, fallbackResult);
+  return { translatedText: fallbackResult, usedNativeApi: false };
+}
+
+export interface TranslationProgressStats {
+  completedSegments: number;
+  totalSegments: number;
+  downloadProgress: number | null;
+  usedNativeApi: boolean;
+  detectedSourceLanguage?: string;
+}
+
+const originalTextStore = new WeakMap<Element, string>();
+
+export function restoreElementsToOriginal(elements: Element[]): void {
+  for (const el of elements) {
+    const orig = originalTextStore.get(el);
+    if (orig !== undefined) {
+      el.textContent = orig;
+    }
+    el.removeAttribute('data-translated-lang');
+    el.removeAttribute('lang');
+  }
+}
+
+export async function translateDomElements(
+  elements: Element[],
+  options: {
+    sourceLanguage: string;
+    targetLanguage: string;
+    signal?: AbortSignal;
+    onProgress?: (stats: TranslationProgressStats) => void;
+  }
+): Promise<TranslationProgressStats> {
+  const { sourceLanguage, targetLanguage, signal, onProgress } = options;
+
+  if (sourceLanguage === targetLanguage || targetLanguage === 'original') {
+    restoreElementsToOriginal(elements);
+    return {
+      completedSegments: elements.length,
+      totalSegments: elements.length,
+      downloadProgress: null,
+      usedNativeApi: true,
+    };
+  }
+
+  // Filter elements that have meaningful text and no child elements we are separately translating
+  const validElements = elements.filter((el) => {
+    const existingOrig = originalTextStore.get(el);
+    const currentText = (existingOrig ?? el.textContent ?? '').trim();
+    return currentText.length > 0;
+  });
+
+  let actualSourceLang = sourceLanguage;
+  if (sourceLanguage === 'auto' && validElements.length > 0) {
+    const sampleText = validElements
+      .slice(0, 3)
+      .map((el) => originalTextStore.get(el) ?? el.textContent ?? '')
+      .join(' ');
+    const detected = await detectSourceLanguage(sampleText);
+    actualSourceLang = detected?.language || 'en';
+  }
+
+  if (actualSourceLang === targetLanguage) {
+    restoreElementsToOriginal(validElements);
+    return {
+      completedSegments: validElements.length,
+      totalSegments: validElements.length,
+      downloadProgress: null,
+      usedNativeApi: true,
+      detectedSourceLanguage: actualSourceLang,
+    };
+  }
+
+  let downloadProgress: number | null = null;
+  let usedNativeApi = false;
+  let completedSegments = 0;
+  const totalSegments = validElements.length;
+
+  const notify = () => {
+    onProgress?.({
+      completedSegments,
+      totalSegments,
+      downloadProgress,
+      usedNativeApi,
+      detectedSourceLanguage: actualSourceLang,
+    });
+  };
+
+  notify();
+
+  for (const el of validElements) {
+    if (signal?.aborted) {
+      throw new DOMException('Translation aborted', 'AbortError');
+    }
+
+    if (!originalTextStore.has(el)) {
+      originalTextStore.set(el, el.textContent ?? '');
+    }
+    const sourceText = originalTextStore.get(el)!;
+
+    const { translatedText, usedNativeApi: isNative } = await translateTextOnDevice(sourceText, {
+      sourceLanguage: actualSourceLang,
+      targetLanguage,
+      signal,
+      onDownloadProgress: (pct) => {
+        downloadProgress = pct;
+        notify();
+      },
+    });
+
+    usedNativeApi = usedNativeApi || isNative;
+    el.textContent = translatedText;
+    el.setAttribute('data-translated-lang', targetLanguage);
+    el.setAttribute('lang', targetLanguage);
+
+    completedSegments++;
+    notify();
+  }
+
+  return {
+    completedSegments,
+    totalSegments,
+    downloadProgress: 100,
+    usedNativeApi,
+    detectedSourceLanguage: actualSourceLang,
+  };
+}

