+  for (const pair of String(cookieHeader).split(';')) {
+    const idx = pair.indexOf('=');
+    if (idx > 0) {
+      const k = pair.slice(0, idx).trim();
+      const v = pair.slice(idx + 1).trim();
+      cookies[k] = decodeURIComponent(v);
+    }
+  }
