+    this._article = this.shadowRoot.querySelector('article');
+    this._img = this.shadowRoot.querySelector('.card-image');
+    this._badgeSlot = this.shadowRoot.querySelector('slot[name="badge"]');
+    this._titleSlot = this.shadowRoot.querySelector('slot[name="title"]');
+    this._descSlot = this.shadowRoot.querySelector('slot[name="description"]');
+    this._priceEl = this.shadowRoot.querySelector('.price');
+    this._roastTag = this.shadowRoot.querySelector('.roast-tag');
+    this._caloriesTag = this.shadowRoot.querySelector('.calories-tag');
+    this._originVal = this.shadowRoot.querySelector('.origin-val');
+    this._notesVal = this.shadowRoot.querySelector('.notes-val');
+    this._favBtn = this.shadowRoot.querySelector('.favorite-btn');
+    this._detailsToggle = this.shadowRoot.querySelector('.details-toggle');
+    this._detailsPanel = this.shadowRoot.querySelector('.details-panel');
+    this._viewDetailsLink = this.shadowRoot.querySelector('.view-details-link');
+    this._addBtn = this.shadowRoot.querySelector('.add-to-order-btn');
+    this._sizeBtns = Array.from(this.shadowRoot.querySelectorAll('.size-btn'));
+
+    this._article.setAttribute('aria-labelledby', 'card-title');
+  }
+
+  connectedCallback() {
+    this._syncAll();
+    this._bindEvents();
+  }
+
+  disconnectedCallback() {
+    this._unbindEvents();
+  }
+
+  attributeChangedCallback(name, oldValue, newValue) {
+    if (oldValue === newValue) return;
+    this._syncAll();
+  }
+
+  get name() {
+    return this.getAttribute('name') || this._titleSlot?.assignedNodes()[0]?.textContent?.trim() || 'Artisanal Coffee';
+  }
+
+  set name(val) {
+    this.setAttribute('name', val);
+  }
+
+  get description() {
+    return this.getAttribute('description') || this._descSlot?.assignedNodes()[0]?.textContent?.trim() || '';
+  }
+
+  set description(val) {
+    this.setAttribute('description', val);
+  }
+
+  get basePrice() {
+    const raw = parseFloat(this.getAttribute('price') || '4.50');
+    return Number.isNaN(raw) ? 4.5 : raw;
+  }
+
+  get currentPrice() {
+    return +(this.basePrice + this._sizeDelta).toFixed(2);
+  }
+
+  get selectedSize() {
+    return this._selectedSize;
+  }
+
+  set selectedSize(size) {
+    const btn = this._sizeBtns.find((b) => b.dataset.size.toLowerCase() === String(size).toLowerCase());
+    if (btn) {
+      this._selectSizeButton(btn, false);
+    }
+  }
+
+  get favorited() {
+    return this.hasAttribute('favorited') && this.getAttribute('favorited') !== 'false';
+  }
+
+  set favorited(val) {
+    if (val) {
+      this.setAttribute('favorited', '');
+    } else {
+      this.removeAttribute('favorited');
+    }
+  }
+
+  _bindEvents() {
+    if (this._bound) return;
+    this._bound = true;
+
+    this._onFavClick = () => {
+      this.favorited = !this.favorited;
+      this.dispatchEvent(
+        new CustomEvent('coffee-favorite', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            name: this.name,
+            favorited: this.favorited
+          }
+        })
+      );
+    };
