+      this._detailsPanel.hidden = !next;
+    };
+
+    this._onViewDetailsClick = (e) => {
+      e.preventDefault();
+      this.dispatchEvent(
+        new CustomEvent('coffee-details', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            name: this.name,
+            description: this.description,
+            price: this.currentPrice,
+            size: this._selectedSize,
