+            notes: this.getAttribute('notes') || 'Rich, aromatic, smooth finish',
+            calories: this.getAttribute('calories') || '120',
+            image: this.getAttribute('image') || '',
+            href: this.getAttribute('href') || '/menu'
+          }
+        })
+      );
+    };
+
+    this._onAddClick = () => {
+      this.dispatchEvent(
+        new CustomEvent('coffee-add-to-cart', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            name: this.name,
+            size: this._selectedSize,
+            price: this.currentPrice,
+            image: this.getAttribute('image') || ''
+          }
+        })
+      );
+
+      const originalText = this._addBtn.textContent;
+      this._addBtn.textContent = 'Added ✓';
+      setTimeout(() => {
+        if (this.isConnected) {
+          this._addBtn.textContent = originalText;
+        }
+      }, 1200);
+    };
+
+    this._onSizeClick = (e) => {
+      const btn = e.target.closest('.size-btn');
+      if (!btn) return;
+      this._selectSizeButton(btn, true);
+    };
+
+    this._onSizeKeydown = (e) => {
+      const currentIdx = this._sizeBtns.indexOf(e.target.closest('.size-btn'));
+      if (currentIdx === -1) return;
+      let nextIdx = -1;
+      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
+        e.preventDefault();
+        nextIdx = (currentIdx + 1) % this._sizeBtns.length;
+      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
+        e.preventDefault();
+        nextIdx = (currentIdx - 1 + this._sizeBtns.length) % this._sizeBtns.length;
+      }
+      if (nextIdx !== -1) {
+        const targetBtn = this._sizeBtns[nextIdx];
+        targetBtn.focus();
+        this._selectSizeButton(targetBtn, true);
+      }
+    };
+
+    this._favBtn.addEventListener('click', this._onFavClick);
+    this._detailsToggle.addEventListener('click', this._onDetailsToggle);
+    this._viewDetailsLink.addEventListener('click', this._onViewDetailsClick);
+    this._addBtn.addEventListener('click', this._onAddClick);
+
+    const sizeGroup = this.shadowRoot.querySelector('.size-selector');
+    sizeGroup.addEventListener('click', this._onSizeClick);
+    sizeGroup.addEventListener('keydown', this._onSizeKeydown);
+  }
+
+  _unbindEvents() {
+    this._bound = false;
+  }
+
+  _selectSizeButton(btn, emitEvent) {
+    this._sizeBtns.forEach((b) => {
+      const active = b === btn;
+      b.setAttribute('aria-checked', String(active));
