+    this._updatePriceDisplay();
+
+    if (emitEvent) {
+      this.dispatchEvent(
+        new CustomEvent('coffee-size-change', {
+          bubbles: true,
+          composed: true,
+          detail: {
+            name: this.name,
+            size: this._selectedSize,
+            price: this.currentPrice
+          }
+        })
+      );
+    }
+  }
+
+  _updatePriceDisplay() {
+    this._priceEl.textContent = `$${this.currentPrice.toFixed(2)}`;
+  }
+
+  _syncAll() {
+    const nameAttr = this.getAttribute('name');
+    if (nameAttr) {
+      this._titleSlot.textContent = nameAttr;
+      const assignedTitle = this._titleSlot.assignedElements()[0];
+      if (assignedTitle && assignedTitle.textContent !== nameAttr) {
+        assignedTitle.textContent = nameAttr;
+      }
+    }
+
+    const descAttr = this.getAttribute('description');
+    if (descAttr) {
+      this._descSlot.textContent = descAttr;
+      const assignedDesc = this._descSlot.assignedElements()[0];
+      if (assignedDesc && assignedDesc.textContent !== descAttr) {
+        assignedDesc.textContent = descAttr;
+      }
+    }
+
+    const badgeAttr = this.getAttribute('badge');
+    this._badgeSlot.textContent = badgeAttr || '';
+    const assignedBadge = this._badgeSlot.assignedElements()[0];
+    if (assignedBadge && badgeAttr !== null) {
+      assignedBadge.textContent = badgeAttr;
+    }
+
+    const imgAttr =
+      this.getAttribute('image') ||
+      'https://images.unsplash.com/photo-1509042239860-f550ce710b93?auto=format&fit=crop&w=800&q=80';
+    this._img.src = imgAttr;
+    this._img.alt = this.name ? `${this.name} coffee drink` : 'Coffee beverage';
+
+    const roast = this.getAttribute('roast');
+    if (roast) {
+      this._roastTag.textContent = roast;
+      this._roastTag.hidden = false;
+    } else {
+      this._roastTag.hidden = true;
+    }
+
+    const calories = this.getAttribute('calories');
+    if (calories) {
+      this._caloriesTag.textContent = `${calories} cal`;
+      this._caloriesTag.hidden = false;
+    } else {
+      this._caloriesTag.hidden = true;
+    }
+
+    this._originVal.textContent = this.getAttribute('origin') || 'Ethically Sourced Blend';
+    this._notesVal.textContent = this.getAttribute('notes') || 'Smooth, balanced aroma';
+
+    const href = this.getAttribute('href') || '/menu';
+    this._viewDetailsLink.setAttribute('href', href);
+    this._viewDetailsLink.setAttribute('aria-label', `View details for ${this.name}`);
+    this._addBtn.setAttribute('aria-label', `Add ${this.name} to order`);
+
+    const isFav = this.favorited;
+    this._favBtn.setAttribute('aria-pressed', String(isFav));
+    this._favBtn.setAttribute(
+      'aria-label',
+      isFav ? `Remove ${this.name} from favorites` : `Save ${this.name} to favorites`
+    );
+    this._favBtn.querySelector('span').textContent = isFav ? '♥' : '♡';
+
+    const sizeAttr = this.getAttribute('size');
+    if (sizeAttr) {
+      const btn = this._sizeBtns.find((b) => b.dataset.size.toLowerCase() === sizeAttr.toLowerCase());
+      if (btn) {
+        this._selectSizeButton(btn, false);
+      }
+    } else {
+      this._updatePriceDisplay();
+    }
+  }
+}
+
+if (!customElements.get('coffee-card')) {
+  customElements.define('coffee-card', CoffeeCard);
+}
