+
+    <div class="controls-bar" role="region" aria-label="Filter coffee menu" part="controls">
+      <div class="filter-tabs" role="tablist" aria-label="Coffee categories">
+        <button type="button" class="tab-btn" role="tab" aria-selected="true" tabindex="0" data-category="all">All Drinks</button>
+        <button type="button" class="tab-btn" role="tab" aria-selected="false" tabindex="-1" data-category="seasonal">Seasonal</button>
+        <button type="button" class="tab-btn" role="tab" aria-selected="false" tabindex="-1" data-category="espresso">Espresso</button>
+        <button type="button" class="tab-btn" role="tab" aria-selected="false" tabindex="-1" data-category="cold-brew">Cold Brew</button>
