+export class CoffeeOrderDrawer extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.appendChild(template.content.cloneNode(true));
+
+    this._items = [];
+    this._overlay = this.shadowRoot.querySelector('.overlay');
+    this._closeBtn = this.shadowRoot.querySelector('.close-btn');
+    this._listEl = this.shadowRoot.querySelector('.items-list');
+    this._totalEl = this.shadowRoot.querySelector('.total-amount');
+    this._pointsEl = this.shadowRoot.querySelector('.points-val');
+    this._announcer = this.shadowRoot.querySelector('#cart-announcer');
+  }
+
+  connectedCallback() {
+    this._onAdd = (e) => {
+      this.addItem(e.detail);
+    };
+
+    this._onToggle = () => {
+      if (this._overlay.hidden) {
+        this.open();
+      } else {
+        this.close();
+      }
+    };
+
+    this._onKeyDown = (e) => {
+      if (!this._overlay.hidden && e.key === 'Escape') {
+        e.preventDefault();
+        this.close();
+      }
+    };
+
+    document.addEventListener('coffee-add-to-cart', this._onAdd);
+    document.addEventListener('coffee-toggle-cart', this._onToggle);
+    document.addEventListener('keydown', this._onKeyDown);
+
+    this._closeBtn.addEventListener('click', () => this.close());
+    this._overlay.addEventListener('click', (e) => {
+      if (e.target === this._overlay) this.close();
+    });
+
+    this._render();
+  }
+
+  disconnectedCallback() {
+    document.removeEventListener('coffee-add-to-cart', this._onAdd);
+    document.removeEventListener('coffee-toggle-cart', this._onToggle);
+    document.removeEventListener('keydown', this._onKeyDown);
+  }
+
+  addItem(item) {
+    if (!item || !item.name) return;
+    const key = `${item.name}|${item.size || 'Medium'}|${item.milk || ''}`;
+    const existing = this._items.find((i) => i.key === key);
+    if (existing) {
+      existing.qty += 1;
+    } else {
+      this._items.push({
+        key,
+        name: item.name,
+        size: item.size || 'Medium',
+        milk: item.milk || '',
+        price: Number(item.price || 4.5),
+        qty: 1
+      });
+    }
+    this._announcer.textContent = `Added ${item.size || 'Medium'} ${item.name} to order.`;
+    this._render();
+    this._emitCartUpdate();
+  }
+
+  open() {
+    this._overlay.hidden = false;
+    this._closeBtn.focus();
+  }
+
+  close() {
+    this._overlay.hidden = true;
+  }
+
+  _emitCartUpdate() {
+    const totalCount = this._items.reduce((sum, i) => sum + i.qty, 0);
+    const totalPrice = this._items.reduce((sum, i) => sum + i.price * i.qty, 0);
+    document.dispatchEvent(
+      new CustomEvent('coffee-cart-updated', {
+        bubbles: true,
+        composed: true,
+        detail: {
+          items: [...this._items],
+          totalCount,
+          totalPrice
+        }
+      })
+    );
+  }
+
+  _render() {
+    this._listEl.innerHTML = '';
+    if (this._items.length === 0) {
+      const li = document.createElement('li');
+      li.className = 'empty-msg';
+      li.textContent = 'Your coffee bag is currently empty. Add a drink from Seasonal Favorites!';
+      this._listEl.appendChild(li);
+      this._totalEl.textContent = '$0.00';
+      this._pointsEl.textContent = '0';
+      return;
+    }
+
+    let total = 0;
+    this._items.forEach((item) => {
+      total += item.price * item.qty;
+      const li = document.createElement('li');
+      li.className = 'item-row';
+
+      const info = document.createElement('div');
+      info.className = 'item-info';
+      const title = document.createElement('strong');
+      title.textContent = item.name;
+      const meta = document.createElement('span');
+      meta.className = 'item-meta';
+      meta.textContent = `${item.size}${item.milk ? ` · ${item.milk}` : ''} · $${(item.price * item.qty).toFixed(2)}`;
+      info.appendChild(title);
+      info.appendChild(meta);
+
+      const controls = document.createElement('div');
+      controls.className = 'qty-controls';
+
+      const decBtn = document.createElement('button');
+      decBtn.type = 'button';
+      decBtn.className = 'qty-btn';
+      decBtn.textContent = '−';
+      decBtn.setAttribute('aria-label', `Decrease quantity of ${item.name}`);
+      decBtn.addEventListener('click', () => {
+        item.qty -= 1;
+        if (item.qty <= 0) {
+          this._items = this._items.filter((x) => x.key !== item.key);
+        }
+        this._render();
+        this._emitCartUpdate();
+      });
+
+      const qtySpan = document.createElement('span');
+      qtySpan.textContent = String(item.qty);
+
+      const incBtn = document.createElement('button');
+      incBtn.type = 'button';
+      incBtn.className = 'qty-btn';
+      incBtn.textContent = '+';
+      incBtn.setAttribute('aria-label', `Increase quantity of ${item.name}`);
+      incBtn.addEventListener('click', () => {
+        item.qty += 1;
+        this._render();
+        this._emitCartUpdate();
+      });
+
+      controls.appendChild(decBtn);
+      controls.appendChild(qtySpan);
+      controls.appendChild(incBtn);
+
+      li.appendChild(info);
+      li.appendChild(controls);
+      this._listEl.appendChild(li);
+    });
+
+    this._totalEl.textContent = `$${total.toFixed(2)}`;
+    this._pointsEl.textContent = String(Math.round(total * 10));
+  }
+}
+
+if (!customElements.get('coffee-order-drawer')) {
+  customElements.define('coffee-order-drawer', CoffeeOrderDrawer);
+}
