+
+      <p class="copyright">&copy; 2026 The Daily Grind Coffee Co. All rights reserved.</p>
+    </div>
+  </footer>
+`;
+
+export class DgFooter extends HTMLElement {
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.appendChild(template.content.cloneNode(true));
+
+    this._form = this.shadowRoot.querySelector('form');
+    this._emailInput = this.shadowRoot.querySelector('#club-email');
+    this._statusEl = this.shadowRoot.querySelector('.status-msg');
+  }
+
+  connectedCallback() {
+    this._form.addEventListener('submit', (e) => {
+      e.preventDefault();
+      const val = this._emailInput.value.trim();
+      if (!val || !val.includes('@')) {
+        this._statusEl.textContent = 'Please enter a valid email address.';
+        this._emailInput.focus();
+        return;
+      }
+      this._statusEl.textContent = `Thanks for subscribing, ${val}! Check your inbox for 15% off.`;
+      this._emailInput.value = '';
+      this.dispatchEvent(
+        new CustomEvent('coffee-newsletter-subscribe', {
+          bubbles: true,
+          composed: true,
+          detail: { email: val }
+        })
+      );
+    });
+  }
+}
