+      flex-direction: column;
+      justify-content: center;
+      align-items: center;
+      color: #ffffff;
+      text-align: center;
+      padding: 40px 20px;
+    }
+
+    .eyebrow {
+      background: rgba(255, 171, 64, 0.22);
+      border: 1px solid var(--hero-accent);
+      color: #ffe0b2;
+      font-size: 0.8rem;
+      font-weight: 700;
+      text-transform: uppercase;
+      letter-spacing: 0.1em;
+      padding: 4px 12px;
+      border-radius: 999px;
+      margin-bottom: 14px;
+    }
+
+    h1 {
+      font-size: clamp(2.2rem, 5vw, 3.2rem);
+      margin: 0 0 1rem 0;
+      line-height: 1.2;
+    }
+
+    p {
+      font-size: 1.15rem;
+      max-width: 600px;
+      margin: 0 0 1.5rem 0;
+      color: rgba(255, 255, 255, 0.92);
+    }
+
+    .cta-group {
+      display: flex;
+      flex-wrap: wrap;
+      gap: 12px;
+      justify-content: center;
+    }
+
+    .btn-primary,
+    .btn-outline {
+      display: inline-flex;
+      align-items: center;
+      justify-content: center;
+      padding: 12px 24px;
+      border-radius: 6px;
+      font-weight: 700;
+      font-size: 0.95rem;
+      text-decoration: none;
+      cursor: pointer;
+      transition: background 0.25s, transform 0.2s;
+    }
+
+    .btn-primary {
+      background: var(--hero-primary);
+      color: #ffffff;
+      border: 1px solid var(--hero-primary);
+    }
+
+    .btn-primary:hover {
+      background: #3e2723;
+    }
+
+    .btn-outline {
+      background: rgba(255, 255, 255, 0.14);
+      color: #ffffff;
+      border: 1px solid rgba(255, 255, 255, 0.7);
+      backdrop-filter: blur(4px);
+    }
+
+    .btn-outline:hover {
+      background: rgba(255, 255, 255, 0.25);
+    }
+
+    .btn-primary:focus-visible,
+    .btn-outline:focus-visible {
+      outline: 3px solid var(--hero-accent);
+      outline-offset: 2px;
+    }
+  </style>
+
+  <header class="hero" part="hero">
+    <span class="eyebrow" part="eyebrow">Small-Batch Roastery</span>
+    <h1 part="heading"><slot name="heading">Wake Up Your Senses</slot></h1>
+    <p part="subheading"><slot name="subheading">Ethically sourced, locally roasted, delivered to your cup.</slot></p>
+    <div class="cta-group" part="actions">
+      <a href="/order-online" class="btn-primary cta-link" part="cta">Order Now</a>
+      <button type="button" class="btn-outline explore-btn" part="secondary-cta">Explore Seasonal Menu ↓</button>
+    </div>
+  </header>
+`;
+
+export class DgHero extends HTMLElement {
+  static get observedAttributes() {
+    return ['heading', 'subheading', 'cta-text', 'cta-href', 'background-image'];
+  }
+
+  constructor() {
+    super();
+    this.attachShadow({ mode: 'open' });
+    this.shadowRoot.appendChild(template.content.cloneNode(true));
+
+    this._headingSlot = this.shadowRoot.querySelector('slot[name="heading"]');
+    this._subSlot = this.shadowRoot.querySelector('slot[name="subheading"]');
+    this._ctaLink = this.shadowRoot.querySelector('.cta-link');
+    this._exploreBtn = this.shadowRoot.querySelector('.explore-btn');
+  }
+
+  connectedCallback() {
+    this._sync();
+    this._exploreBtn.addEventListener('click', () => {
+      const menuSection = document.querySelector('coffee-menu-section, main');
+      if (menuSection) {
+        menuSection.scrollIntoView({ behavior: 'smooth' });
+      }
+    });
+  }
+
+  attributeChangedCallback() {
+    this._sync();
+  }
+
+  _sync() {
+    if (this.hasAttribute('heading') && this._headingSlot.assignedNodes().length === 0) {
+      this._headingSlot.textContent = this.getAttribute('heading');
+    }
+    if (this.hasAttribute('subheading') && this._subSlot.assignedNodes().length === 0) {
+      this._subSlot.textContent = this.getAttribute('subheading');
+    }
+    if (this.hasAttribute('cta-text')) {
+      this._ctaLink.textContent = this.getAttribute('cta-text');
+    }
+    if (this.hasAttribute('cta-href')) {
+      this._ctaLink.setAttribute('href', this.getAttribute('cta-href'));
+    }
+    if (this.hasAttribute('background-image')) {
+      this.style.setProperty('--hero-bg', `url('${this.getAttribute('background-image')}')`);
+    }
+  }
+}
+
+if (!customElements.get('dg-hero')) {
+  customElements.define('dg-hero', DgHero);
+}
