+
+    .logout-link {
+      border: 1px solid var(--nav-accent);
+      padding: 5px 12px;
+      border-radius: 4px;
+    }
+
+    .cart-trigger {
+      background: var(--nav-accent);
+      color: #3e2723;
+      border: none;
+      padding: 6px 14px;
+      border-radius: 999px;
+      font-weight: 700;
+      font-size: 0.88rem;
+      cursor: pointer;
+      display: inline-flex;
+      align-items: center;
+      gap: 6px;
+      transition: transform 0.2s, background 0.2s;
+    }
+
+    .cart-trigger:hover {
+      background: #ffd180;
+    }
+
+    .cart-trigger:focus-visible {
+      outline: 3px solid #ffffff;
+      outline-offset: 2px;
+    }
+
+    .cart-badge {
+      background: #3e2723;
+      color: #ffffff;
+      border-radius: 999px;
+      padding: 1px 7px;
+      font-size: 0.78rem;
+    }
+
+    .menu-toggle {
+      display: none;
+      background: transparent;
+      border: 1px solid rgba(255, 255, 255, 0.5);
+      color: #ffffff;
+      padding: 6px 10px;
