+              orderSec.scrollIntoView({ behavior: 'smooth' });
+            }
+          });
+        }
+      }
+
+      registerBrowserTools();
+      if (document.readyState === 'loading') {
+        document.addEventListener('DOMContentLoaded', initDOMListeners);
+      } else {
+        initDOMListeners();
+      }
+    })();
+  </script>
+
 </body>

